window.AUTH=window.AUTH||{};window.AUTH["20-1472"]={"d":"20-1472","id":"2021/20-1472","n":"Boechler, P.C. v. Commissioner of Internal Revenue","briefs":[{"k":"petitioner","label":"Brief of petitioner Boechler, P.C.","date":"2021-11-15","url":"https://www.supremecourt.gov/DocketPDF/20/20-1472/199957/20211115154143941_2021-11-15%20No.%2020-1472%20Boechler%20Merits%20Brief%20for%20Petitioner%20w%20addendum.pdf","side":"pet","n":118},{"k":"respondent","label":"Brief of respondent Commissioner of Internal Revenue","date":"2021-12-15","url":"https://www.supremecourt.gov/DocketPDF/20/20-1472/205272/20211215180925444_20-1472bsUnitedStates.pdf","side":"res","n":82},{"k":"reply","label":"Reply of petitioner Boechler, P.C.","date":"2021-12-30","url":"https://www.supremecourt.gov/DocketPDF/20/20-1472/206950/20211230134029851_2021-12-30%20No.%2020-1472%20Boechler%20Merits%20Reply%20Brief.pdf","side":"pet","n":65}],"opinion":"https://www.supremecourt.gov/opinions/21pdf/596us1r26_o6p1.pdf","tr":true,"items":[{"t":"case","label":"Arbaugh v. Y & H Corp.","cite":"546 U.S. 500","y":2006,"id":"2005/04-944","sc":1,"op":1,"ar":2,"sum":"The Court held that the number-of-employees requirement is an element of the merits of a Title VII claim, not a jurisdictional limitation.","sumSrc":"Oyez","by":{"0":"15, 16, 22, 31","1":"17, 38"}},{"t":"case","label":"Bogart v. Commissioner, T.C. Memo. 2014-46","cite":"2014 WL 1041443","y":2014,"court":"Mar. 18","by":{"0":"39"}},{"t":"case","label":"Bowen v. City of New York","cite":"476 U.S. 467","y":1986,"id":"1985/84-1923","sc":1,"sum":"The Social Security Act provides benefits to disabled persons under two programs administered by the Social Security Administration (SSA): the Social Security Disability Insurance Program (SSD) and the Supplemental Security Income Program (SSI). Regulations for both programs establish a five-step \"sequential evaluation\" process for determining eligibility for benefits. The initial determination of whether an …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42","2":"20, 22"}},{"t":"case","label":"Bowles v. Russell","cite":"551 U.S. 205","y":2007,"id":"2006/06-5306","sc":1,"sum":"The Court ruled that, even though Bowles was relying on the mistaken order of the District Court, the Circuit Court was correct to dismiss his untimely appeal.","sumSrc":"Oyez","by":{"0":"33","1":"18, 27, 33","2":"5"}},{"t":"case","label":"Cyan, Inc. v. Beaver County Employees Retirement Fund","cite":"138 S. Ct. 1061","y":2018,"id":"2017/15-1439","sc":1,"sum":"The Court held that that the Securities Litigation Uniform Standards Act of 1998 does not strip state courts of jurisdiction to hear claims under the Securities Act of 1933, nor does it permit defendants to remove class actions alleging only 1933 Act claims from state to federal court.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"Deal v. United States","cite":"508 U.S. 129","y":1993,"id":"1992/91-8199","sc":1,"sum":"The Court held that Deal's second through sixth convictions in a single proceeding arose \"in the case of his second or subsequent conviction\" within the meaning of section 924(c)(1), finding that the statute was not ambiguous.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"Dolan v. United States","cite":"560 U.S. 605","y":2010,"id":"2009/09-367","sc":1,"sum":"The Court held that federal courts may enter a restitution order beyond the time prescribed under the Mandatory Victims Restitution Act if certain qualifications are met.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Duggan v. Commissioner","cite":"879 F.3d 1029","y":2018,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/879/1029/","by":{"0":"10","1":"13, 17, 19"}},{"t":"case","label":"EPA v. EME Homer City Generation, L.P.","cite":"572 U.S. 489","y":2014,"id":"2013/12-1182","sc":1,"op":1,"sum":"The Court held that the EPA has an absolute mandate to require states to meet federal standards set forth in the Clean Air Act.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Fort Bend County v. Davis","cite":"139 S. Ct. 1843","y":2019,"id":"2018/18-525","sc":1,"op":1,"sum":"The charge-filing precondition to suit set out in Title VII of the Civil Rights Act of 1964 is not a jurisdictional requirement.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"passim","1":"12, 18","2":"6"}},{"t":"case","label":"Page(s) Gomez-Perez v. Potter","cite":"553 U.S. 474","y":2008,"id":"2007/06-1321","sc":1,"sum":"Noting the similarity between these statutes and the ADEA, Alito concluded that Congress had intended to include a retaliation prohibition in the ADEA. Chief Justice John G. Roberts and Justice Clarence Thomas filed dissenting opinions each joined in part by Justice Antonin Scalia.","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"Gonzalez v. Thaler","cite":"565 U.S. 134","y":2012,"id":"2011/10-895","sc":1,"sum":"The Court held that a prisoner who does not seek review in a state’s highest court faces final judgment for the purposes of Section 2244(d)(1)(A) upon “expiration of the time for seeking such review.”","sumSrc":"Oyez","by":{"0":"passim","1":"13, 19","2":"7"}},{"t":"case","label":"Gray v. Commissioner","cite":"138 T.C. 295","y":2012,"url":"https://www.courtlistener.com/c/T.C./138/295/","by":{"0":"9","1":"11"}},{"t":"case","label":"Guralnik v. Commissioner","cite":"146 T.C. 230","y":2016,"url":"https://www.courtlistener.com/c/T.C./146/230/","by":{"0":"9","1":"11, 19, 28"}},{"t":"case","label":"Hamer v. Neighborhood Housing Services of Chicago","cite":"138 S. Ct. 13","y":2017,"id":"2017/16-658","sc":1,"sum":"A case in which Court held that Federal Rule of Appellate Procedure 4(a)(5)(C), which places a time limit on appeals, is not jurisdictional because it is a court-made rule rather than a statute.","sumSrc":"Oyez","by":{"0":"15, 16, 35","1":"22"}},{"t":"case","label":"Henderson v. Shinseki","cite":"562 U.S. 428","y":2011,"id":"2010/09-1036","sc":1,"op":3,"ar":6,"sum":"The Court held that missing the deadline for filing a notice of appeal with the Veterans Court did not bar a plaintiff from making a claim.","sumSrc":"Oyez","by":{"0":"passim","1":"13, 22, 38","2":"7, 15, 17, 20"}},{"t":"case","label":"Hinck v. United States","cite":"550 U.S. 501","y":2007,"id":"2006/06-376","sc":1,"sum":"The Court reasoned that its ruling was consistent with the principle that when Congress enacts a detailed, specific judicial remedy (such as 6404(e)(1)) where there was no remedy before, the new remedy will be regarded as exclusive.","sumSrc":"Oyez","by":{"0":"33"}},{"t":"case","label":"Holland v. Florida","cite":"560 U.S. 631","y":2010,"id":"2009/09-5327","sc":1,"op":1,"ar":1,"sum":"The Court held that a state prisoner who has exhausted their appeals process in their state has one year to file a writ of habeas corpus, with certain exceptions (including attorney misconduct) that may allow the courts to relax that deadline.","sumSrc":"Oyez","by":{"0":"passim","1":"46, 47","2":"15, 17, 22"}},{"t":"case","label":"INS v. St. Cyr","cite":"533 U.S. 289","y":2001,"id":"2000/00-767","sc":1,"sum":"The Court held that habeas jurisdiction was not repealed by AEDPA and IIRIRA.","sumSrc":"Oyez","by":{"0":"31"}},{"t":"case","label":"Irwin v. Department of Veterans Affairs","cite":"498 U.S. 89","y":1990,"id":"1990/89-5867","sc":1,"op":1,"ar":2,"sum":"The Supreme Court held that lower courts have consistently held that notice to an attorney's office qualifies as notice to the client. \"The practical effect of a contrary rule would be to encourage factual disputes about when actual notice was received, and thereby create uncertainty in an area of the law where certainty is much to be desired,\" wrote Chief Justice Rehnquist.","sumSrc":"Oyez","by":{"0":"35, 36, 37","1":"41, 47"}},{"t":"case","label":"John R. Sand & Gravel Co. v. United States","cite":"552 U.S. 130","y":2008,"id":"2007/06-1164","sc":1,"sum":"In a seven-member majority opinion written by Justice Stephen G. Breyer, the Court upheld the Federal Circuit ruling that the statute of limitations was \"jurisdictional,\" or a predicate for court authority. Breyer referred to roughly five decades of the Court's case law to determine that the doctrine of stare decisis required it to follow the time limit and dismiss John R. Sand's claim.","sumSrc":"Oyez","by":{"0":"33","1":"33, 41","2":"13"}},{"t":"case","label":"Page(s) Kontrick v. Ryan","cite":"540 U.S. 443","y":2004,"id":"2003/02-819","sc":1,"op":1,"sum":"The Court held that Kontrick lost the right to invoke Rule 4004's time limitation because he did so after the bankruptcy court reached the merits of Ryan's objection. The Court rejected Kontrick's claim that Rule 4004 is \"jurisdictional\" and that it trumps other considerations whenever raised in proceedings.","sumSrc":"Oyez","by":{"0":"14, 21, 37"}},{"t":"case","label":"Landgraf v. USI Film Products","cite":"511 U.S. 244","y":1994,"id":"1993/92-757","sc":1,"sum":"Section 102 does not apply to a Title VII case that was pending on appeal when the 1991 Act was enacted.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"14"}},{"t":"case","label":"Lundsford v. Commissioner","cite":"117 T.C. 183","y":2001,"url":"https://www.courtlistener.com/c/T.C./117/183/","by":{"0":"40"}},{"t":"case","label":"Mayo Foundation for Medical Education & Research v. United States","cite":"562 U.S. 44","y":2011,"id":"2010/09-837","sc":1,"op":2,"sum":"A case in which the Court upheld the Treasury Department's rule that treats medical residents as full-time employees, and therefore not exempt from the payment of payroll taxes.","sumSrc":"Oyez","by":{"0":"43","1":"46"}},{"t":"case","label":"McLane v. Commissioner, T.C. Memo. 2018-149","cite":"2018 WL 4350097","y":2018,"court":"Sept. 11","by":{"0":"42"}},{"t":"case","label":"Minerva Surgical, Inc. v. Hologic, Inc.","cite":"141 S. Ct. 2298","y":2021,"id":"2020/20-440","sc":1,"sum":"The well-grounded patent law doctrine of assignor estoppel applies only when the assignor’s claim of invalidity contradicts explicit or implicit representations the assignor made in assigning the patent.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"36"}},{"t":"case","label":"Musacchio v. United States","cite":"577 U.S. 237","y":2016,"id":"2015/14-1095","sc":1,"sum":"The Court determined that the law of the case doctrine does not require that the sufficiency of evidence be measured against the elements laid out in the jury instructions when those elements require the government to prove more than the statute requires and the government did not object at trial. The Court also determined that a statute of limitations defense that is not raised at trial is not reviewable on appeal.","sumSrc":"Oyez","by":{"0":"15, 16","1":"12, 17, 18, 19"}},{"t":"case","label":"Myers v. Commissioner","cite":"928 F.3d 1025","y":2019,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/928/1025/","sum":"Noting that the analogous 26 U.S.C. § 7623(b)(4) does not use the word “if”.","sumSrc":"brief:0","by":{"0":"11, 19, 21, 30","1":"13, 33, 34","2":"3"}},{"t":"case","label":"Nutraceutical Corp. v. Lambert","cite":"139 S. Ct. 710","y":2019,"id":"2018/17-1094","sc":1,"sum":"Federal Rule of Civil Procedure 23(f), which establishes a 14-day deadline to seek permission to appeal an order granting or denying class certification, is not subject to equitable tolling.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"44","1":"40, 41"}},{"t":"case","label":"Page(s) Pereira v. Sessions","cite":"138 S. Ct. 2105","y":2018,"id":"2017/17-459","sc":1,"sum":"The Court held that a notice to appear for a removal hearing that does not specify the place and time of the hearing does not trigger the stop-time rule of 8 U.S.C. § 1229b(b)(1), which gives the attorney general discretion to cancel removal for an alien who, among other criteria, has been continuously physically present in the country for at least ten years.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"Reed Elsevier, Inc. v. Muchnick","cite":"559 U.S. 154","y":2010,"id":"2009/08-103","sc":1,"sum":"The Court held that the registration requirement of Section 411(a) of the Copyright Act is a precondition to filing a copyright infringement claim.","sumSrc":"Oyez","by":{"0":"15, 32, 33, 34","1":"18, 23"}},{"t":"case","label":"Republic National Bank of Miami v. United States","cite":"506 U.S. 80","y":1992,"id":"1992/91-767","sc":1,"sum":"The Government filed a civil action in the District Court, alleging that a particular residence was subject to forfeiture under 21 U. S. C. §881(a)(6) because its owner had purchased it with narcotics trafficking proceeds. After the United States Marshal seized the property, petitioner Bank, which claimed a lien under a recorded mortgage, agreed to the Government's request for a sale of the property, the proceeds of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"14"}},{"t":"case","label":"Sebelius v. Auburn Regional Medical Center","cite":"568 U.S. 145","y":2013,"id":"2012/11-1231","sc":1,"op":4,"sum":"The Court held that the statute of limitations for filing a claim with the Provider Reimbursement Review Board may be extended up to 3 years.","sumSrc":"Oyez","by":{"0":"passim","1":"passim","2":"4, 18"}},{"t":"case","label":"Sego v. Commissioner","cite":"114 T.C. 604","y":2000,"url":"https://www.courtlistener.com/c/T.C./114/604/","by":{"0":"39"}},{"t":"case","label":"Sossamon v. Texas","cite":"563 U.S. 277","y":2011,"id":"2010/08-1438","sc":1,"op":1,"sum":"The Court held that a person may not sue a state official in his individual capacity for damages under the Religious Land Use and Institutional Persons Act.","sumSrc":"Oyez","by":{"0":"31","2":"2, 3"}},{"t":"case","label":"United States v. Beggerly","cite":"524 U.S. 38","y":1998,"id":"1997/97-731","sc":1,"sum":"The Court held that the Court of Appeals erred in concluding that this was a sufficient basis to justify reopening the judgment. \"[A]n independent action should be available only to prevent a grave miscarriage of justice,\" wrote Chief Justice Rehnquist, \"it should be obvious that [the Beggerlys'] allegations do not nearly approach this demanding standard.\" The Court also concluded that the Court of Appeals extension of the Quiet Title Act's statutory period by equitable tolling was unwarranted, given its generous nature.","sumSrc":"Oyez","by":{"0":"43","1":"43","2":"15"}},{"t":"case","label":"United States v. Brockamp","cite":"519 U.S. 347","y":1997,"id":"1996/95-1225","sc":1,"op":8,"ar":2,"sum":"The Court ruled that Congress did not intend the \"equitable tolling\" doctrine to apply to the Internal Revenue Code of 1986's time limitations for filing tax refund claims.","sumSrc":"Oyez","by":{"0":"40, 41, 42, 43, 45","1":"42, 43, 45","2":"17, 20"}},{"t":"case","label":"United States v. Kwai Fun Wong","cite":"575 U.S. 402","y":2015,"id":"2014/13-1074","sc":1,"op":2,"sum":"The Court held that the statutes of limitations provisions of the Federal Tort Claims Act are subject to equitable tolling.","sumSrc":"Oyez","by":{"0":"passim","1":"12, 13, 17, 22, 26, 38","2":"5, 13, 14, 23"}},{"t":"case","label":"V.L. v. E.L.","cite":"577 U.S. 404","y":2016,"id":"2015/15-648","sc":1,"sum":"The Court determined that the Full Faith and Credit Clause of the Constitution requires the Alabama state courts to recognize a Georgia state court’s adoption order.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Page(s) Volpicelli v. United States","cite":"777 F.3d 1042","y":2015,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/777/1042/","sum":"Holding that statutory deadline to file wrongful levy action against government in 26 U.S.C. § 6532(c) is subject to equitable tolling, notwithstanding Brockamp.","sumSrc":"brief:0","by":{"0":"43"}},{"t":"case","label":"Weinberger v. Salfi","cite":"422 U.S. 749","y":1975,"id":"1974/74-214","sc":1,"op":1,"ar":1,"sum":"After her husband of less than six months died, appellee widow filed applications for mother's Social Security insurance benefits for herself and child's insurance benefits for her daughter by a previous marriage, but the Social Security Administration (SSA), both initially and on reconsideration at the regional level, denied the applications on the basis of the duration-of-relationship requirements of the Social …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18"}},{"t":"case","label":"Young v. United States","cite":"535 U.S. 43","y":2002,"id":"2001/00-1567","sc":1,"op":1,"sum":"The Court held section 507(a)(8)(A)(i)'s lookback period is tolled during the pendency of a prior bankruptcy petition. The Court reasoned that the three-year lookback period is a limitations period subject to traditional principles of equitable tolling and that nothing in the Bankruptcy Code precluded the equitable tolling of the lookback period.","sumSrc":"Oyez","by":{"0":"36, 37, 42, 44","2":"17, 22"}},{"t":"case","label":"Zipes v. Trans World Airlines, Inc.","cite":"455 U.S. 385","y":1982,"id":"1981/78-1545","sc":1,"sum":"In 1970, the union then representing flight attendants employed by respondent Trans World Airlines, Inc. (TWA), brought a federal-court class action alleging that TWA practiced unlawful sex discrimination in violation of Title VII of the Civil Rights Act of 1964 by its policy of grounding all female flight attendants who became mothers while their male counterparts who became fathers were permitted to continue …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26, 27, 38","1":"22"}},{"t":"usc","label":"18 U.S.C. § 1001","url":"https://www.law.cornell.edu/uscode/text/18/1001","by":{"0":"21"}},{"t":"usc","label":"18 U.S.C. § 1519","url":"https://www.law.cornell.edu/uscode/text/18/1519","by":{"0":"21"}},{"t":"usc","label":"26 U.S.C. § 6015","url":"https://www.law.cornell.edu/uscode/text/26/6015","subs":["(e)(1)(A)"],"stext":{"head":"§6015. Relief from joint and several liability on joint return","paras":[[0,"(a) In general"],[0,"Notwithstanding section 6013(d)(3)—"],[1,"(1) an individual who has made a joint return may elect to seek relief under the procedures prescribed under subsection (b); and"],[1,"(2) if such individual is eligible to elect the application of subsection (c), such individual may, in addition to any election under paragraph (1), elect to limit such individual's liability for any deficiency with respect to such joint return in the manner prescribed under subsection (c)."],[0,"Any determination under this section shall be made without regard to community property laws."],[0,"(b) Procedures for relief from liability applicable to all joint filers"],[0,"(1) In general"],[1,"Under procedures prescribed by the Secretary, if—"],[2,"(A) a joint return has been made for a taxable year;"],[2,"(B) on such return there is an understatement of tax attributable to erroneous items of one individual filing the joint return;"],[2,"(C) the other individual filing the joint return establishes that in signing the return he or she did not know, and had no reason to know, that there was such understatement;"],[2,"(D) taking into account all the facts and circumstances, it is inequitable to hold the other individual liable for the deficiency in tax for such taxable year attributable to such understatement; and"],[2,"(E) the other individual elects (in such form as the Secretary may prescribe) the benefits of this subsection not later than the date which is 2 years after the date the Secretary has begun collection activities with respect to the individual making the election,"],[1,"then the other individual shall be relieved of liability for tax (including interest, penalties, and other amounts) for such taxable year to the extent such liability is attributable to such understatement."],[0,"(2) Apportionment of relief"],[1,"If an individual who, but for paragraph (1)(C), would be relieved of liability under paragraph (1), establishes that in signing the return such individual did not know, and had no reason to know, the extent of such understatement, then such individual shall be relieved of liability for tax (including interest, penalties, and other amounts) for such taxable year to the extent that such liability is attributable to the portion of such understatement of which such individual did not know and had no reason to know."],[0,"(3) Understatement"],[1,"For purposes of this subsection, the term \"understatement\" has the meaning given to such term by section 6662(d)(2)(A)."],[0,"(c) Procedures to limit liability for taxpayers no longer married or taxpayers legally separated or not living together"],[0,"(1) In general"],[1,"Except as provided in this subsection, if an individual who has made a joint return for any taxable year elects the application of this subsection, the individual's liability for any deficiency which is assessed with respect to the return shall not exceed the portion of such deficiency properly allocable to the individual under subsection (d)."],[0,"(2) Burden of proof"],[1,"Except as provided in subparagraph (A)(ii) or (C) of paragraph (3), each individual who elects the application of this subsection shall have the burden of proof with respect to establishing the portion of any deficiency allocable to such individual."],[0,"(3) Election"],[0,"(A) Individuals eligible to make election"],[0,"(i) In general"],[3,"An individual shall only be eligible to elect the application of this subsection if—"],[4,"(I) at the time such election is filed, such individual is no longer married to, or is legally separated from, the individual with whom such individual filed the joint return to which the election relates; or"],[4,"(II) such individual was not a member of the same household as the individual with whom such joint return was filed at any time during the 12-month period ending on the date such election is filed."],[0,"(ii) Certain taxpayers ineligible to elect"],[3,"If the Secretary demonstrates that assets were transferred between individuals filing a joint return as part of a fraudulent scheme by such individuals, an election under this subsection by either individual shall be invalid (and section 6013(d)(3) shall apply to the joint return)."],[0,"(B) Time for election"],[2,"An election under this subsection for any taxable year may be made at any time after a deficiency for such year is asserted but not later than 2 years after the date on which the Secretary has begun collection activities with respect to the individual making the election."],[0,"(C) Election not valid with respect to certain deficiencies"],[2,"If the Secretary demonstrates that an individual making an election under this subsection had actual knowledge, at the time such individual signed the return, of any item giving rise to a deficiency (or portion thereof) which is not allocable to such individual under subsection (d), such election shall not apply to such deficiency (or portion). This subparagraph shall not apply where the individual with actual knowledge establishes that such individual signed the return under duress."],[0,"(4) Liability increased by reason of transfers of property to avoid tax"],[0,"(A) In general"],[2,"Notwithstanding any other provision of this subsection, the portion of the deficiency for which the individual electing the application of this subsection is liable (without regard to this paragraph) shall be increased by the value of any disqualified asset transferred to the individual."],[0,"(B) Disqualified asset"],[2,"For purposes of this paragraph—"],[0,"(i) In general"],[3,"The term \"disqualified asset\" means any property or right to property transferred to an individual making the election under this subsection with respect to a joint return by the other individual filing such joint return if the principal purpose of the transfer was the avoidance of tax or payment of tax."],[0,"(ii) Presumption"],[0,"(I) In general"],[4,"For purposes of clause (i), except as provided in subclause (II), any transfer which is made after the date which is 1 year before the date on which the first letter of proposed deficiency which allows the taxpayer an opportunity for administrative review in the Internal Revenue Service Independent Office of Appeals is sent shall be presumed to have as its principal purpose the avoidance of tax or payment of tax."],[0,"(II) Exceptions"],[4,"Subclause (I) shall not apply to any transfer pursuant to a decree of divorce or separate maintenance or a written instrument incident to such a decree or to any transfer which an individual establishes did not have as its principal purpose the avoidance of tax or payment of tax."],[0,"(d) Allocation of deficiency"],[0,"For purposes of subsection (c)—"],[0,"(1) In general"],[1,"The portion of any deficiency on a joint return allocated to an individual shall be the amount which bears the same ratio to such deficiency as the net amount of items taken into account in computing the deficiency and allocable to the individual under paragraph (3) bears to the net amount of all items taken into account in computing the deficiency."],[0,"(2) Separate treatment of certain items"],[1,"If a deficiency (or portion thereof) is attributable to—"],[2,"(A) the disallowance of a credit; or"],[2,"(B) any tax (other than tax imposed by section 1 or 55) required to be included with the joint return;"],[1,"and such item is allocated to one individual under paragraph (3), such deficiency (or portion) shall be allocated to such individual. Any such item shall not be taken into account under paragraph (1)."],[0,"(3) Allocation of items giving rise to the deficiency"],[1,"For purposes of this subsection—"],[0,"(A) In general"],[2,"Except as provided in paragraphs (4) and (5), any item giving rise to a deficiency on a joint return shall be allocated to individuals filing the return in the same manner as it would have been allocated if the individuals had filed separate returns for the taxable year."],[0,"(B) Exception where other spouse benefits"],[2,"Under rules prescribed by the Secretary, an item otherwise allocable to an individual under subparagraph (A) shall be allocated to the other individual filing the joint return to the extent the item gave rise to a tax benefit on the joint return to the other individual."],[0,"(C) Exception for fraud"],[2,"The Secretary may provide for an allocation of any item in a manner not prescribed by subparagraph (A) if the Secretary establishes that such allocation is appropriate due to fraud of one or both individuals."],[0,"(4) Limitations on separate returns disregarded"],[1,"If an item of deduction or credit is disallowed in its entirety solely because a separate return is filed, such disallowance shall be disregarded and the item shall be computed as if a joint return had been filed and then allocated between the spouses appropriately. A similar rule shall apply for purposes of section 86."],[0,"(5) Child's liability"],[1,"If the liability of a child of a taxpayer is included on a joint return, such liability shall be disregarded in computing the separate liability of either spouse and such liability shall be allocated appropriately between the spouses."],[0,"(e) Petition for review by Tax Court"],[0,"(1) In general"],[1,"In the case of an individual against whom a deficiency has been asserted and who elects to have subsection (b) or (c) apply, or in the case of an individual who requests equitable relief under subsection (f)—"],[0,"(A) In general"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/6015?type=usc&year=mostrecent&link-type=html"},"head":"§6015. Relief from joint and several liability on joint return","tname":"Internal Revenue Code","by":{"0":"22","2":"6"}},{"t":"usc","label":"26 U.S.C. § 6320","url":"https://www.law.cornell.edu/uscode/text/26/6320","subs":["(a)","(b)","(c)"],"stext":{"head":"§6320. Notice and opportunity for hearing upon filing of notice of lien","paras":[[0,"(a) Requirement of notice"],[0,"(1) In general"],[1,"The Secretary shall notify in writing the person described in section 6321 of the filing of a notice of lien under section 6323."],[0,"(2) Time and method for notice"],[1,"The notice required under paragraph (1) shall be—"],[2,"(A) given in person;"],[2,"(B) left at the dwelling or usual place of business of such person; or"],[2,"(C) sent by certified or registered mail to such person's last known address,"],[1,"not more than 5 business days after the day of the filing of the notice of lien."],[0,"(3) Information included with notice"],[1,"The notice required under paragraph (1) shall include in simple and nontechnical terms—"],[2,"(A) the amount of unpaid tax;"],[2,"(B) the right of the person to request a hearing during the 30-day period beginning on the day after the 5-day period described in paragraph (2);"],[2,"(C) the administrative appeals available to the taxpayer with respect to such lien and the procedures relating to such appeals;"],[2,"(D) the provisions of this title and procedures relating to the release of liens on property; and"],[2,"(E) the provisions of section 7345 relating to the certification of seriously delinquent tax debts and the denial, revocation, or limitation of passports of individuals with such debts pursuant to section 32101 of the FAST Act."],[0,"(b) Right to fair hearing"],[0,"(1) In general"],[1,"If the person requests a hearing in writing under subsection (a)(3)(B) and states the grounds for the requested hearing, such hearing shall be held by the Internal Revenue Service Independent Office of Appeals."],[0,"(2) One hearing per period"],[1,"A person shall be entitled to only one hearing under this section with respect to the taxable period to which the unpaid tax specified in subsection (a)(3)(A) relates."],[0,"(3) Impartial officer"],[1,"The hearing under this subsection shall be conducted by an officer or employee who has had no prior involvement with respect to the unpaid tax specified in subsection (a)(3)(A) before the first hearing under this section or section 6330. A taxpayer may waive the requirement of this paragraph."],[0,"(4) Coordination with section 6330"],[1,"To the extent practicable, a hearing under this section shall be held in conjunction with a hearing under section 6330."],[0,"(c) Conduct of hearing; review; suspensions"],[0,"For purposes of this section, subsections (c), (d) (other than paragraph (3)(B) thereof), (e), and (g) of section 6330 shall apply."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/6320?type=usc&year=mostrecent&link-type=html"},"head":"§6320. Notice and opportunity for hearing upon filing of notice of lien","tname":"Internal Revenue Code","by":{"0":"5, 5, 5, 6","1":"4"}},{"t":"usc","label":"26 U.S.C. § 6321","url":"https://www.law.cornell.edu/uscode/text/26/6321","by":{"0":"3"}},{"t":"usc","label":"26 U.S.C. § 6323","url":"https://www.law.cornell.edu/uscode/text/26/6323","subs":["(a)","(f)"],"by":{"0":"3, 3"}},{"t":"usc","label":"26 U.S.C. § 6330","url":"https://www.law.cornell.edu/uscode/text/26/6330","subs":["(a)","(b)","(c)","(c)(1)","(c)(2)","(c)(2)(A)(i)","(c)(2)(A)(ii)","(c)(2)(A)(iii)","(c)(2)(B)","(c)(3)","(c)(3)(C)","(d)(1)","(d)(2)","(e)(1)","(e)(2)","(f)","(e)(1)(2000)","(g)","(c)(2)(A)","(d)(1)(A)"],"stext":{"head":"§6330. Notice and opportunity for hearing before levy","paras":[[0,"(a) Requirement of notice before levy"],[0,"(1) In general"],[1,"No levy may be made on any property or right to property of any person unless the Secretary has notified such person in writing of their right to a hearing under this section before such levy is made. Such notice shall be required only once for the taxable period to which the unpaid tax specified in paragraph (3)(A) relates."],[0,"(2) Time and method for notice"],[1,"The notice required under paragraph (1) shall be—"],[2,"(A) given in person;"],[2,"(B) left at the dwelling or usual place of business of such person; or"],[2,"(C) sent by certified or registered mail, return receipt requested, to such person's last known address;"],[1,"not less than 30 days before the day of the first levy with respect to the amount of the unpaid tax for the taxable period."],[0,"(3) Information included with notice"],[1,"The notice required under paragraph (1) shall include in simple and nontechnical terms—"],[2,"(A) the amount of unpaid tax;"],[2,"(B) the right of the person to request a hearing during the 30-day period under paragraph (2); and"],[2,"(C) the proposed action by the Secretary and the rights of the person with respect to such action, including a brief statement which sets forth—"],[3,"(i) the provisions of this title relating to levy and sale of property;"],[3,"(ii) the procedures applicable to the levy and sale of property under this title;"],[3,"(iii) the administrative appeals available to the taxpayer with respect to such levy and sale and the procedures relating to such appeals;"],[3,"(iv) the alternatives available to taxpayers which could prevent levy on property (including installment agreements under section 6159); and"],[3,"(v) the provisions of this title and procedures relating to redemption of property and release of liens on property."],[0,"(b) Right to fair hearing"],[0,"(1) In general"],[1,"If the person requests a hearing in writing under subsection (a)(3)(B) and states the grounds for the requested hearing, such hearing shall be held by the Internal Revenue Service Independent Office of Appeals."],[0,"(2) One hearing per period"],[1,"A person shall be entitled to only one hearing under this section with respect to the taxable period to which the unpaid tax specified in subsection (a)(3)(A) relates."],[0,"(3) Impartial officer"],[1,"The hearing under this subsection shall be conducted by an officer or employee who has had no prior involvement with respect to the unpaid tax specified in subsection (a)(3)(A) before the first hearing under this section or section 6320. A taxpayer may waive the requirement of this paragraph."],[0,"(c) Matters considered at hearing"],[0,"In the case of any hearing conducted under this section—"],[0,"(1) Requirement of investigation"],[1,"The appeals officer shall at the hearing obtain verification from the Secretary that the requirements of any applicable law or administrative procedure have been met."],[0,"(2) Issues at hearing"],[0,"(A) In general"],[2,"The person may raise at the hearing any relevant issue relating to the unpaid tax or the proposed levy, including—"],[3,"(i) appropriate spousal defenses;"],[3,"(ii) challenges to the appropriateness of collection actions; and"],[3,"(iii) offers of collection alternatives, which may include the posting of a bond, the substitution of other assets, an installment agreement, or an offer-in-compromise."],[0,"(B) Underlying liability"],[2,"The person may also raise at the hearing challenges to the existence or amount of the underlying tax liability for any tax period if the person did not receive any statutory notice of deficiency for such tax liability or did not otherwise have an opportunity to dispute such tax liability."],[0,"(3) Basis for the determination"],[1,"The determination by an appeals officer under this subsection shall take into consideration—"],[2,"(A) the verification presented under paragraph (1);"],[2,"(B) the issues raised under paragraph (2); and"],[2,"(C) whether any proposed collection action balances the need for the efficient collection of taxes with the legitimate concern of the person that any collection action be no more intrusive than necessary."],[0,"(4) Certain issues precluded"],[1,"An issue may not be raised at the hearing if—"],[2,"(A)(i) the issue was raised and considered at a previous hearing under section 6320 or in any other previous administrative or judicial proceeding; and"],[2,"(ii) the person seeking to raise the issue participated meaningfully in such hearing or proceeding;"],[2,"(B) the issue meets the requirement of clause (i) or (ii) of section 6702(b)(2)(A); or"],[2,"(C) a final determination has been made with respect to such issue in a proceeding brought under subchapter C of chapter 63."],[1,"This paragraph shall not apply to any issue with respect to which subsection (d)(3)(B) applies."],[0,"(d) Proceeding after hearing"],[0,"(1) Petition for review by Tax Court"],[1,"The person may, within 30 days of a determination under this section, petition the Tax Court for review of such determination (and the Tax Court shall have jurisdiction with respect to such matter)."],[0,"(2) Suspension of running of period for filing petition in title 11 cases"],[1,"In the case of a person who is prohibited by reason of a case under title 11, United States Code, from filing a petition under paragraph (1) with respect to a determination under this section, the running of the period prescribed by such subsection for filing such a petition with respect to such determination shall be suspended for the period during which the person is so prohibited from filing such a petition, and for 30 days thereafter."],[0,"(3) Jurisdiction retained at IRS Independent Office of Appeals"],[1,"The Internal Revenue Service Independent Office of Appeals shall retain jurisdiction with respect to any determination made under this section, including subsequent hearings requested by the person who requested the original hearing on issues regarding—"],[2,"(A) collection actions taken or proposed with respect to such determination; and"],[2,"(B) after the person has exhausted all administrative remedies, a change in circumstances with respect to such person which affects such determination."],[0,"(e) Suspension of collections and statute of limitations"],[0,"(1) In general"],[1,"Except as provided in paragraph (2), if a hearing is requested under subsection (a)(3)(B), the levy actions which are the subject of the requested hearing and the running of any period of limitations under section 6502 (relating to collection after assessment), section 6531 (relating to criminal prosecutions), or section 6532 (relating to other suits) shall be suspended for the period during which such hearing, and appeals therein, are pending. In no event shall any such period expire before the 90th day after the day on which there is a final determination in such hearing. Notwithstanding the provisions of section 7421(a), the beginning of a levy or proceeding during the time the suspension under this paragraph is in force may be enjoined by a proceeding in the proper court, including the Tax Court. The Tax Court shall have no jurisdiction under this paragraph to enjoin any action or proceeding unless a timely appeal has been filed under subsection (d)(1) and then only in respect of the unpaid tax or proposed levy to which the determination being appealed relates."],[0,"(2) Levy upon appeal"],[1,"Paragraph (1) shall not apply to a levy action while an appeal is pending if the underlying tax liability is not at issue in the appeal and the court determines that the Secretary has shown good cause not to suspend the levy."],[0,"(f) Exceptions"],[0,"If—"],[1,"(1) the Secretary has made a finding under the last sentence of section 6331(a) that the collection of tax is in jeopardy,"],[1,"(2) the Secretary has served a levy on a State to collect a Federal tax liability from a State tax refund,"],[1,"(3) the Secretary has served a disqualified employment tax levy, or"],[1,"(4) the Secretary has served a Federal contractor levy,"],[0,"this section shall not apply, except that the taxpayer shall be given the opportunity for the hearing described in this section within a reasonable period of time after the levy."],[0,"(g) Frivolous requests for hearing, etc."],[0,"Notwithstanding any other provision of this section, if the Secretary determines that any portion of a request for a hearing under this section or section 6320 meets the requirement of clause (i) or (ii) of section 6702(b)(2)(A), then the Secretary may treat such portion as if it were never submitted and such portion shall not be subject to any further administrative or judicial review."],[0,"(h) Definitions related to exceptions"],[0,"For purposes of subsection (f)—"],[0,"(1) Disqualified employment tax levy"],[1,"A disqualified employment tax levy is any levy in connection with the collection of employment taxes for any taxable period if the person subject to the levy (or any predecessor thereof) requested a hearing under this section with respect to unpaid employment taxes arising in the most recent 2-year period before the beginning of the taxable period with respect to which the levy is served. For purposes of the preceding sentence, the term \"employment taxes\" means any taxes under chapter 21, 22, 23, or 24."],[0,"(2) Federal contractor levy"],[1,"A Federal contractor levy is any levy if the person whose property is subject to the levy (or any predecessor thereof) is a Federal contractor."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/6330?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§6330. Notice and opportunity for hearing before levy","tname":"Internal Revenue Code","by":{"0":"26, 5, 5, 30, 6, 5, 38, 5, 5, 5, 6, 6, 39, passim, 23, 42, 46, 7, 31, 7, 7","1":"6, 8, 45, 8, 4, 5, 6","2":"17, 17, 17, 2, 20, 8, 9, 9, 11, 12, 22, 22"}},{"t":"usc","label":"26 U.S.C. § 6331","url":"https://www.law.cornell.edu/uscode/text/26/6331","by":{"0":"4"}},{"t":"usc","label":"26 U.S.C. § 6404","url":"https://www.law.cornell.edu/uscode/text/26/6404","subs":["(g)","(h)"],"stext":{"head":"§6404. Abatements","paras":[[0,"(a) General rule"],[0,"The Secretary is authorized to abate the unpaid portion of the assessment of any tax or any liability in respect thereof, which—"],[1,"(1) is excessive in amount, or"],[1,"(2) is assessed after the expiration of the period of limitation properly applicable thereto, or"],[1,"(3) is erroneously or illegally assessed."],[0,"(b) No claim for abatement of income, estate, and gift taxes"],[0,"No claim for abatement shall be filed by a taxpayer in respect of an assessment of any tax imposed under subtitle A or B."],[0,"(c) Small tax balances"],[0,"The Secretary is authorized to abate the unpaid portion of the assessment of any tax, or any liability in respect thereof, if the Secretary determines under uniform rules prescribed by the Secretary that the administration and collection costs involved would not warrant collection of the amount due."],[0,"(d) Assessments attributable to certain mathematical errors by Internal Revenue Service"],[0,"In the case of an assessment of any tax imposed by chapter 1 attributable in whole or in part to a mathematical error described in section 6213(g)(2)(A), if the return was prepared by an officer or employee of the Internal Revenue Service acting in his official capacity to provide assistance to taxpayers in the preparation of income tax returns, the Secretary is authorized to abate the assessment of all or any part of any interest on such deficiency for any period ending on or before the 30th day following the date of notice and demand by the Secretary for payment of the deficiency."],[0,"(e) Abatement of interest attributable to unreasonable errors and delays by Internal Revenue Service"],[0,"(1) In general"],[1,"In the case of any assessment of interest on—"],[2,"(A) any deficiency attributable in whole or in part to any unreasonable error or delay by an officer or employee of the Internal Revenue Service (acting in his official capacity) in performing a ministerial or managerial act, or"],[2,"(B) any payment of any tax described in section 6212(a) to the extent that any unreasonable error or delay in such payment is attributable to such an officer or employee being erroneous or dilatory in performing a ministerial or managerial act,"],[1,"the Secretary may abate the assessment of all or any part of such interest for any period. For purposes of the preceding sentence, an error or delay shall be taken into account only if no significant aspect of such error or delay can be attributed to the taxpayer involved, and after the Internal Revenue Service has contacted the taxpayer in writing with respect to such deficiency or payment."],[0,"(2) Interest abated with respect to erroneous refund check"],[1,"The Secretary shall abate the assessment of all interest on any erroneous refund under section 6602 until the date demand for repayment is made, unless—"],[2,"(A) the taxpayer (or a related party) has in any way caused such erroneous refund, or"],[2,"(B) such erroneous refund exceeds $50,000."],[0,"(f) Abatement of any penalty or addition to tax attributable to erroneous written advice by the Internal Revenue Service"],[0,"(1) In general"],[1,"The Secretary shall abate any portion of any penalty or addition to tax attributable to erroneous advice furnished to the taxpayer in writing by an officer or employee of the Internal Revenue Service, acting in such officer's or employee's official capacity."],[0,"(2) Limitations"],[1,"Paragraph (1) shall apply only if—"],[2,"(A) the written advice was reasonably relied upon by the taxpayer and was in response to a specific written request of the taxpayer, and"],[2,"(B) the portion of the penalty or addition to tax did not result from a failure by the taxpayer to provide adequate or accurate information."],[0,"(g) Suspension of interest and certain penalties where Secretary fails to contact taxpayer"],[0,"(1) Suspension"],[0,"(A) In general"],[2,"In the case of an individual who files a return of tax imposed by subtitle A for a taxable year on or before the due date for the return (including extensions), if the Secretary does not provide a notice to the taxpayer specifically stating the taxpayer's liability and the basis for the liability before the close of the 36-month period beginning on the later of—"],[3,"(i) the date on which the return is filed; or"],[3,"(ii) the due date of the return without regard to extensions,"],[2,"the Secretary shall suspend the imposition of any interest, penalty, addition to tax, or additional amount with respect to any failure relating to the return which is computed by reference to the period of time the failure continues to exist and which is properly allocable to the suspension period."],[0,"(B) Separate application"],[2,"This paragraph shall be applied separately with respect to each item or adjustment."],[1,"If, after the return for a taxable year is filed, the taxpayer provides to the Secretary 1 or more signed written documents showing that the taxpayer owes an additional amount of tax for the taxable year, clause (i) shall be applied by substituting the date the last of the documents was provided for the date on which the return is filed."],[0,"(2) Exceptions"],[1,"Paragraph (1) shall not apply to—"],[2,"(A) any penalty imposed by section 6651;"],[2,"(B) any interest, penalty, addition to tax, or additional amount in a case involving fraud;"],[2,"(C) any interest, penalty, addition to tax, or additional amount with respect to any tax liability shown on the return;"],[2,"(D) any interest, penalty, addition to tax, or additional amount with respect to any gross misstatement;"],[2,"(E) any interest, penalty, addition to tax, or additional amount with respect to any reportable transaction with respect to which the requirement of section 6664(d)(3)(A) is not met and any listed transaction (as defined in 6707A(c)); or"],[2,"(F) any criminal penalty."],[0,"(3) Suspension period"],[1,"For purposes of this subsection, the term \"suspension period\" means the period—"],[2,"(A) beginning on the day after the close of the 36-month period under paragraph (1); and"],[2,"(B) ending on the date which is 21 days after the date on which notice described in paragraph (1)(A) is provided by the Secretary."],[0,"(h) Judicial review of request for abatement of interest"],[0,"(1) In general"],[1,"The Tax Court shall have jurisdiction over any action brought by a taxpayer who meets the requirements referred to in section 7430(c)(4)(A)(ii) to determine whether the Secretary's failure to abate interest under this section was an abuse of discretion, and may order an abatement, if such action is brought—"],[2,"(A) at any time after the earlier of—"],[3,"(i) the date of the mailing of the Secretary's final determination not to abate such interest, or"],[3,"(ii) the date which is 180 days after the date of the filing with the Secretary (in such form as the Secretary may prescribe) of a claim for abatement under this section, and"],[2,"(B) not later than the date which is 180 days after the date described in subparagraph (A)(i)."],[0,"(2) Special rules"],[0,"(A) Date of mailing"],[2,"Rules similar to the rules of section 6213 shall apply for purposes of determining the date of the mailing referred to in paragraph (1)."],[0,"(B) Relief"],[2,"Rules similar to the rules of section 6512(b) shall apply for purposes of this subsection."],[0,"(C) Review"],[2,"An order of the Tax Court under this subsection shall be reviewable in the same manner as a decision of the Tax Court, but only with respect to the matters determined in such order."],[0,"(i) Cross reference"],[2,"For authority to suspend running of interest, etc. by reason of Presidentially declared disaster or terroristic or military action, see section 7508A."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/6404?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§6404. Abatements","tname":"Internal Revenue Code","by":{"0":"22, 22","2":"6"}},{"t":"usc","label":"26 U.S.C. § 6502","url":"https://www.law.cornell.edu/uscode/text/26/6502","subs":["(a)"],"stext":{"head":"§6502. Collection after assessment","paras":[[0,"(a) Length of period"],[0,"Where the assessment of any tax imposed by this title has been made within the period of limitation properly applicable thereto, such tax may be collected by levy or by a proceeding in court, but only if the levy is made or the proceeding begun—"],[1,"(1) within 10 years after the assessment of the tax, or"],[1,"(2) if—"],[2,"(A) there is an installment agreement between the taxpayer and the Secretary, prior to the date which is 90 days after the expiration of any period for collection agreed upon in writing by the Secretary and the taxpayer at the time the installment agreement was entered into; or"],[2,"(B) there is a release of levy under section 6343 after such 10-year period, prior to the expiration of any period for collection agreed upon in writing by the Secretary and the taxpayer before such release."],[0,"If a timely proceeding in court for the collection of a tax is commenced, the period during which such tax may be collected by levy shall be extended and shall not expire until the liability for the tax (or a judgment against the taxpayer arising from such liability) is satisfied or becomes unenforceable."],[0,"(b) Date when levy is considered made"],[0,"The date on which a levy on property or rights to property is made shall be the date on which the notice of seizure provided in section 6335(a) is given."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/6502?type=usc&year=mostrecent&link-type=html"},"head":"§6502. Collection after assessment","tname":"Internal Revenue Code","by":{"0":"7","2":"12"}},{"t":"usc","label":"26 U.S.C. § 6511","url":"https://www.law.cornell.edu/uscode/text/26/6511","subs":["(a)","(b)(1)","(b)(2)(A)","(b)(2)(B)","(d)(1)"],"stext":{"head":"§6511. Limitations on credit or refund","paras":[[0,"(a) Period of limitation on filing claim"],[0,"Claim for credit or refund of an overpayment of any tax imposed by this title in respect of which tax the taxpayer is required to file a return shall be filed by the taxpayer within 3 years from the time the return was filed or 2 years from the time the tax was paid, whichever of such periods expires the later, or if no return was filed by the taxpayer, within 2 years from the time the tax was paid. Claim for credit or refund of an overpayment of any tax imposed by this title which is required to be paid by means of a stamp shall be filed by the taxpayer within 3 years from the time the tax was paid."],[0,"(b) Limitation on allowance of credits and refunds"],[0,"(1) Filing of claim within prescribed period"],[1,"No credit or refund shall be allowed or made after the expiration of the period of limitation prescribed in subsection (a) for the filing of a claim for credit or refund, unless a claim for credit or refund is filed by the taxpayer within such period."],[0,"(2) Limit on amount of credit or refund"],[0,"(A) Limit where claim filed within 3-year period"],[2,"If the claim was filed by the taxpayer during the 3-year period prescribed in subsection (a), the amount of the credit or refund shall not exceed the portion of the tax paid within the period, immediately preceding the filing of the claim, equal to 3 years plus the period of any extension of time for filing the return. If the tax was required to be paid by means of a stamp, the amount of the credit or refund shall not exceed the portion of the tax paid within the 3 years immediately preceding the filing of the claim."],[0,"(B) Limit where claim not filed within 3-year period"],[2,"If the claim was not filed within such 3-year period, the amount of the credit or refund shall not exceed the portion of the tax paid during the 2 years immediately preceding the filing of the claim."],[0,"(C) Limit if no claim filed"],[2,"If no claim was filed, the credit or refund shall not exceed the amount which would be allowable under subparagraph (A) or (B), as the case may be, if claim was filed on the date the credit or refund is allowed."],[0,"(c) Special rules applicable in case of extension of time by agreement"],[0,"If an agreement under the provisions of section 6501(c)(4) extending the period for assessment of a tax imposed by this title is made within the period prescribed in subsection (a) for the filing of a claim for credit or refund—"],[0,"(1) Time for filing claim"],[1,"The period for filing claim for credit or refund or for making credit or refund if no claim is filed, provided in subsections (a) and (b)(1), shall not expire prior to 6 months after the expiration of the period within which an assessment may be made pursuant to the agreement or any extension thereof under section 6501(c)(4)."],[0,"(2) Limit on amount"],[1,"If a claim is filed, or a credit or refund is allowed when no claim was filed, after the execution of the agreement and within 6 months after the expiration of the period within which an assessment may be made pursuant to the agreement or any extension thereof, the amount of the credit or refund shall not exceed the portion of the tax paid after the execution of the agreement and before the filing of the claim or the making of the credit or refund, as the case may be, plus the portion of the tax paid within the period which would be applicable under subsection (b)(2) if a claim had been filed on the date the agreement was executed."],[0,"(3) Claims not subject to special rule"],[1,"This subsection shall not apply in the case of a claim filed, or credit or refund allowed if no claim is filed, either—"],[2,"(A) prior to the execution of the agreement or"],[2,"(B) more than 6 months after the expiration of the period within which an assessment may be made pursuant to the agreement or any extension thereof."],[0,"(d) Special rules applicable to income taxes"],[0,"(1) Seven-year period of limitation with respect to bad debts and worthless securities"],[1,"If the claim for credit or refund relates to an overpayment of tax imposed by subtitle A on account of—"],[2,"(A) The deductibility by the taxpayer, under section 166 or section 832(c), of a debt as a debt which became worthless, or, under section 165(g), of a loss from worthlessness of a security, or"],[2,"(B) The effect that the deductibility of a debt or loss described in subparagraph (A) has on the application to the taxpayer of a carryover,"],[1,"in lieu of the 3-year period of limitation prescribed in subsection (a), the period shall be 7 years from the date prescribed by law for filing the return for the year with respect to which the claim is made. If the claim for credit or refund relates to an overpayment on account of the effect that the deductibility of such a debt or loss has on the application to the taxpayer of a carryback, the period shall be either 7 years from the date prescribed by law for filing the return for the year of the net operating loss which results in such carryback or the period prescribed in paragraph (2) of this subsection, whichever expires the later. In the case of a claim described in this paragraph the amount of the credit or refund may exceed the portion of the tax paid within the period prescribed in subsection (b)(2) or (c), whichever is applicable, to the extent of the amount of the overpayment attributable to the deductibility of items described in this paragraph."],[0,"(2) Special period of limitation with respect to net operating loss or capital loss carrybacks"],[0,"(A) Period of limitation"],[2,"If the claim for credit or refund relates to an overpayment attributable to a net operating loss carryback or a capital loss carryback, in lieu of the 3-year period of limitation prescribed in subsection (a), the period shall be that period which ends 3 years after the time prescribed by law for filing the return (including extensions thereof) for the taxable year of the net operating loss or net capital loss which results in such carryback, or the period prescribed in subsection (c) in respect of such taxable year, whichever expires later. In the case of such a claim, the amount of the credit or refund may exceed the portion of the tax paid within the period provided in subsection (b)(2) or (c), whichever is applicable, to the extent of the amount of the overpayment attributable to such carryback."],[0,"(B) Applicable rules"],[0,"(i) In general"],[3,"If the allowance of a credit or refund of an overpayment of tax attributable to a net operating loss carryback or a capital loss carryback is otherwise prevented by the operation of any law or rule of law other than section 7122 (relating to compromises), such credit or refund may be allowed or made, if claim therefor is filed within the period provided in subparagraph (A) of this paragraph."],[0,"(ii) Tentative carryback adjustments"],[3,"If the allowance of an application, credit, or refund of a decrease in tax determined under section 6411(b) is otherwise prevented by the operation of any law or rule of law other than section 7122, such application, credit, or refund may be allowed or made if application for a tentative carryback adjustment is made within the period provided in section 6411(a)."],[0,"(iii) Determinations by courts to be conclusive"],[3,"In the case of any such claim for credit or refund or any such application for a tentative carryback adjustment, the determination by any court, including the Tax Court, in any proceeding in which the decision of the court has become final, shall be conclusive except with respect to—"],[4,"(I) the net operating loss deduction and the effect of such deduction, and"],[4,"(II) the determination of a short-term capital loss and the effect of such short-term capital loss, to the extent that such deduction or short-term capital loss is affected by a carryback which was not an issue in such proceeding."],[0,"(3) Special rules relating to foreign tax credit"],[0,"(A) Special period of limitation with respect to foreign taxes paid or accrued"],[2,"If the claim for credit or refund relates to an overpayment attributable to any taxes paid or accrued to any foreign country or to any possession of the United States for which credit is allowed against the tax imposed by subtitle A in accordance with the provisions of section 901 or the provisions of any treaty to which the United States is a party, in lieu of the 3-year period of limitation prescribed in subsection (a), the period shall be 10 years from the date prescribed by law for filing the return for the year in which such taxes were actually paid or accrued."],[0,"(B) Exception in the case of foreign taxes paid or accrued"],[2,"In the case of a claim described in subparagraph (A), the amount of the credit or refund may exceed the portion of the tax paid within the period provided in subsection (b) or (c), whichever is applicable, to the extent of the amount of the overpayment attributable to the allowance of a credit for the taxes described in subparagraph (A)."],[0,"(4) Special period of limitation with respect to certain credit carrybacks"],[0,"(A) Period of limitation"],[2,"If the claim for credit or refund relates to an overpayment attributable to a credit carryback, in lieu of the 3-year period of limitation prescribed in subsection (a), the period shall be that period which ends 3 years after the time prescribed by law for filing the return (including extensions thereof) for the taxable year of the unused credit which results in such carryback (or, with respect to any portion of a credit carryback from a taxable year attributable to a net operating loss carryback, capital loss carryback, or other credit carryback from a subsequent taxable year, the period shall be that period which ends 3 years after the time prescribed by law for filing the return, including extensions thereof, for such subsequent taxable year) or the period prescribed in subsection (c) in respect of such taxable year, whichever expires later. In the case of such a claim, the amount of the credit or refund may exceed the portion of the tax paid within the period provided in subsection (b)(2) or (c), whichever is applicable, to the extent of the amount of the overpayment attributable to such carryback."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/6511?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§6511. Limitations on credit or refund","tname":"Internal Revenue Code","by":{"0":"40, 40, 40, 40, 40, 40"}},{"t":"usc","label":"26 U.S.C. § 6514","url":"https://www.law.cornell.edu/uscode/text/26/6514","by":{"0":"40"}},{"t":"usc","label":"26 U.S.C. § 6721","url":"https://www.law.cornell.edu/uscode/text/26/6721","subs":["(a)(2)","(e)"],"by":{"0":"8, 8"}},{"t":"usc","label":"26 U.S.C. § 7122","url":"https://www.law.cornell.edu/uscode/text/26/7122","by":{"0":"6"}},{"t":"usc","label":"26 U.S.C. § 7421","url":"https://www.law.cornell.edu/uscode/text/26/7421","subs":["(a)"],"stext":{"head":"§7421. Prohibition of suits to restrain assessment or collection","paras":[[0,"(a) Tax"],[0,"Except as provided in sections 6015(e), 6212(a) and (c), 6213(a), 6232(c), 6330(e)(1), 6331(i), 6672(c), 6694(c), 7426(a) and (b)(1), 7429(b), and 7436, no suit for the purpose of restraining the assessment or collection of any tax shall be maintained in any court by any person, whether or not such person is the person against whom such tax was assessed."],[0,"(b) Liability of transferee or fiduciary"],[0,"No suit shall be maintained in any court for the purpose of restraining the assessment or collection (pursuant to the provisions of chapter 71) of—"],[1,"(1) the amount of the liability, at law or in equity, of a transferee of property of a taxpayer in respect of any internal revenue tax, or"],[1,"(2) the amount of the liability of a fiduciary under section 3713(b) of title 31, United States Code, in respect of any such tax."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/7421?type=usc&year=mostrecent&link-type=html"},"head":"§7421. Prohibition of suits to restrain assessment or collection","tname":"Internal Revenue Code","by":{"0":"31","1":"3, 23"}},{"t":"usc","label":"26 U.S.C. § 7442","url":"https://www.law.cornell.edu/uscode/text/26/7442","by":{"0":"24"}},{"t":"usc","label":"26 U.S.C. § 7482","url":"https://www.law.cornell.edu/uscode/text/26/7482","subs":["(a)"],"by":{"0":"7"}},{"t":"usc","label":"26 U.S.C. § 7502","url":"https://www.law.cornell.edu/uscode/text/26/7502","subs":["(a)(1)"],"stext":{"head":"§7502. Timely mailing treated as timely filing and paying","paras":[[0,"(a) General rule"],[0,"(1) Date of delivery"],[1,"If any return, claim, statement, or other document required to be filed, or any payment required to be made, within a prescribed period or on or before a prescribed date under authority of any provision of the internal revenue laws is, after such period or such date, delivered by United States mail to the agency, officer, or office with which such return, claim, statement, or other document is required to be filed, or to which such payment is required to be made, the date of the United States postmark stamped on the cover in which such return, claim, statement, or other document, or payment, is mailed shall be deemed to be the date of delivery or the date of payment, as the case may be."],[0,"(2) Mailing requirements"],[1,"This subsection shall apply only if—"],[2,"(A) the postmark date falls within the prescribed period or on or before the prescribed date—"],[3,"(i) for the filing (including any extension granted for such filing) of the return, claim, statement, or other document, or"],[3,"(ii) for making the payment (including any extension granted for making such payment), and"],[2,"(B) the return, claim, statement, or other document, or payment was, within the time prescribed in subparagraph (A), deposited in the mail in the United States in an envelope or other appropriate wrapper, postage prepaid, properly addressed to the agency, officer, or office with which the return, claim, statement, or other document is required to be filed, or to which such payment is required to be made."],[0,"(b) Postmarks"],[0,"This section shall apply in the case of postmarks not made by the United States Postal Service only if and to the extent provided by regulations prescribed by the Secretary."],[0,"(c) Registered and certified mailing; electronic filing"],[0,"(1) Registered mail"],[1,"For purposes of this section, if any return, claim, statement, or other document, or payment, is sent by United States registered mail—"],[2,"(A) such registration shall be prima facie evidence that the return, claim, statement, or other document was delivered to the agency, officer, or office to which addressed; and"],[2,"(B) the date of registration shall be deemed the postmark date."],[0,"(2) Certified mail; electronic filing"],[1,"The Secretary is authorized to provide by regulations the extent to which the provisions of paragraph (1) with respect to prima facie evidence of delivery and the postmark date shall apply to certified mail and electronic filing."],[0,"(d) Exceptions"],[0,"This section shall not apply with respect to—"],[1,"(1) the filing of a document in, or the making of a payment to, any court other than the Tax Court,"],[1,"(2) currency or other medium of payment unless actually received and accounted for, or"],[1,"(3) returns, claims, statements, or other documents, or payments, which are required under any provision of the internal revenue laws or the regulations thereunder to be delivered by any method other than by mailing."],[0,"(e) Mailing of deposits"],[0,"(1) Date of deposit"],[1,"If any deposit required to be made (pursuant to regulations prescribed by the Secretary under section 6302(c)) on or before a prescribed date is, after such date, delivered by the United States mail to the bank, trust company, domestic building and loan association, or credit union authorized to receive such deposit, such deposit shall be deemed received by such bank, trust company, domestic building and loan association, or credit union on the date the deposit was mailed."],[0,"(2) Mailing requirements"],[1,"Paragraph (1) shall apply only if the person required to make the deposit establishes that—"],[2,"(A) the date of mailing falls on or before the second day before the prescribed date for making the deposit (including any extension of time granted for making such deposit), and"],[2,"(B) the deposit was, on or before such second day, mailed in the United States in an envelope or other appropriate wrapper, postage prepaid, properly addressed to the bank, trust company, domestic building and loan association, or credit union authorized to receive such deposit."],[1,"In applying subsection (c) for purposes of this subsection, the term \"payment\" includes \"deposit\", and the reference to the postmark date refers to the date of mailing."],[0,"(3) No application to certain deposits"],[1,"Paragraph (1) shall not apply with respect to any deposit of $20,000 or more by any person who is required to deposit any tax more than once a month."],[0,"(f) Treatment of private delivery services"],[0,"(1) In general"],[1,"Any reference in this section to the United States mail shall be treated as including a reference to any designated delivery service, and any reference in this section to a postmark by the United States Postal Service shall be treated as including a reference to any date recorded or marked as described in paragraph (2)(C) by any designated delivery service."],[0,"(2) Designated delivery service"],[1,"For purposes of this subsection, the term \"designated delivery service\" means any delivery service provided by a trade or business if such service is designated by the Secretary for purposes of this section. The Secretary may designate a delivery service under the preceding sentence only if the Secretary determines that such service—"],[2,"(A) is available to the general public,"],[2,"(B) is at least as timely and reliable on a regular basis as the United States mail,"],[2,"(C) records electronically to its data base, kept in the regular course of its business, or marks on the cover in which any item referred to in this section is to be delivered, the date on which such item was given to such trade or business for delivery, and"],[2,"(D) meets such other criteria as the Secretary may prescribe."],[0,"(3) Equivalents of registered and certified mail"],[1,"The Secretary may provide a rule similar to the rule of paragraph (1) with respect to any service provided by a designated delivery service which is substantially equivalent to United States registered or certified mail."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/7502?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§7502. Timely mailing treated as timely filing and paying","tname":"Internal Revenue Code","by":{"0":"46, 9","2":"9"}},{"t":"usc","label":"26 U.S.C. § 7503","url":"https://www.law.cornell.edu/uscode/text/26/7503","by":{"0":"9"}},{"t":"usc","label":"26 U.S.C. § 7508","url":"https://www.law.cornell.edu/uscode/text/26/7508","subs":["(a)","(c)"],"by":{"0":"46, 46"}},{"t":"usc","label":"26 U.S.C. § 7508A","url":"https://www.law.cornell.edu/uscode/text/26/7508A","subs":["(a)","(d)"],"by":{"0":"46, 46"}},{"t":"usc","label":"26 U.S.C. § 7623","url":"https://www.law.cornell.edu/uscode/text/26/7623","subs":["(b)(4)"],"by":{"0":"11, 21"}},{"t":"usc","label":"26 U.S.C. § 7803","url":"https://www.law.cornell.edu/uscode/text/26/7803","subs":["(c)","(c)(2)(B)(ii)(IX)"],"by":{"0":"47, 47"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"usc","label":"28 U.S.C. § 1331","url":"https://www.law.cornell.edu/uscode/text/28/1331","stext":{"head":"§1331. Federal question","paras":[[0,"The district courts shall have original jurisdiction of all civil actions arising under the Constitution, laws, or treaties of the United States."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1331?type=usc&year=mostrecent&link-type=html"},"head":"§1331. Federal question","tname":"Judiciary and Judicial Procedure","by":{"0":"24","2":"5"}},{"t":"usc","label":"28 U.S.C. § 1332","url":"https://www.law.cornell.edu/uscode/text/28/1332","subs":["(a)"],"stext":{"head":"§1332. Diversity of citizenship; amount in controversy; costs","paras":[[0,"(a) The district courts shall have original jurisdiction of all civil actions where the matter in controversy exceeds the sum or value of $75,000, exclusive of interest and costs, and is between—"],[1,"(1) citizens of different States;"],[1,"(2) citizens of a State and citizens or subjects of a foreign state, except that the district courts shall not have original jurisdiction under this subsection of an action between citizens of a State and citizens or subjects of a foreign state who are lawfully admitted for permanent residence in the United States and are domiciled in the same State;"],[1,"(3) citizens of different States and in which citizens or subjects of a foreign state are additional parties; and"],[1,"(4) a foreign state, defined in section 1603(a) of this title, as plaintiff and citizens of a State or of different States."],[0,"(b) Except when express provision therefor is otherwise made in a statute of the United States, where the plaintiff who files the case originally in the Federal courts is finally adjudged to be entitled to recover less than the sum or value of $75,000, computed without regard to any setoff or counterclaim to which the defendant may be adjudged to be entitled, and exclusive of interest and costs, the district court may deny costs to the plaintiff and, in addition, may impose costs on the plaintiff."],[0,"(c) For the purposes of this section and section 1441 of this title—"],[1,"(1) a corporation shall be deemed to be a citizen of every State and foreign state by which it has been incorporated and of the State or foreign state where it has its principal place of business, except that in any direct action against the insurer of a policy or contract of liability insurance, whether incorporated or unincorporated, to which action the insured is not joined as a party-defendant, such insurer shall be deemed a citizen of—"],[2,"(A) every State and foreign state of which the insured is a citizen;"],[2,"(B) every State and foreign state by which the insurer has been incorporated; and"],[2,"(C) the State or foreign state where the insurer has its principal place of business; and"],[1,"(2) the legal representative of the estate of a decedent shall be deemed to be a citizen only of the same State as the decedent, and the legal representative of an infant or incompetent shall be deemed to be a citizen only of the same State as the infant or incompetent."],[0,"(d)(1) In this subsection—"],[1,"(A) the term \"class\" means all of the class members in a class action;"],[1,"(B) the term \"class action\" means any civil action filed under rule 23 of the Federal Rules of Civil Procedure or similar State statute or rule of judicial procedure authorizing an action to be brought by 1 or more representative persons as a class action;"],[1,"(C) the term \"class certification order\" means an order issued by a court approving the treatment of some or all aspects of a civil action as a class action; and"],[1,"(D) the term \"class members\" means the persons (named or unnamed) who fall within the definition of the proposed or certified class in a class action."],[0,"(2) The district courts shall have original jurisdiction of any civil action in which the matter in controversy exceeds the sum or value of $5,000,000, exclusive of interest and costs, and is a class action in which—"],[1,"(A) any member of a class of plaintiffs is a citizen of a State different from any defendant;"],[1,"(B) any member of a class of plaintiffs is a foreign state or a citizen or subject of a foreign state and any defendant is a citizen of a State; or"],[1,"(C) any member of a class of plaintiffs is a citizen of a State and any defendant is a foreign state or a citizen or subject of a foreign state."],[0,"(3) A district court may, in the interests of justice and looking at the totality of the circumstances, decline to exercise jurisdiction under paragraph (2) over a class action in which greater than one-third but less than two-thirds of the members of all proposed plaintiff classes in the aggregate and the primary defendants are citizens of the State in which the action was originally filed based on consideration of—"],[1,"(A) whether the claims asserted involve matters of national or interstate interest;"],[1,"(B) whether the claims asserted will be governed by laws of the State in which the action was originally filed or by the laws of other States;"],[1,"(C) whether the class action has been pleaded in a manner that seeks to avoid Federal jurisdiction;"],[1,"(D) whether the action was brought in a forum with a distinct nexus with the class members, the alleged harm, or the defendants;"],[1,"(E) whether the number of citizens of the State in which the action was originally filed in all proposed plaintiff classes in the aggregate is substantially larger than the number of citizens from any other State, and the citizenship of the other members of the proposed class is dispersed among a substantial number of States; and"],[1,"(F) whether, during the 3-year period preceding the filing of that class action, 1 or more other class actions asserting the same or similar claims on behalf of the same or other persons have been filed."],[0,"(4) A district court shall decline to exercise jurisdiction under paragraph (2)—"],[1,"(A)(i) over a class action in which—"],[2,"(I) greater than two-thirds of the members of all proposed plaintiff classes in the aggregate are citizens of the State in which the action was originally filed;"],[2,"(II) at least 1 defendant is a defendant—"],[3,"(aa) from whom significant relief is sought by members of the plaintiff class;"],[3,"(bb) whose alleged conduct forms a significant basis for the claims asserted by the proposed plaintiff class; and"],[3,"(cc) who is a citizen of the State in which the action was originally filed; and"],[2,"(III) principal injuries resulting from the alleged conduct or any related conduct of each defendant were incurred in the State in which the action was originally filed; and"],[1,"(ii) during the 3-year period preceding the filing of that class action, no other class action has been filed asserting the same or similar factual allegations against any of the defendants on behalf of the same or other persons; or"],[1,"(B) two-thirds or more of the members of all proposed plaintiff classes in the aggregate, and the primary defendants, are citizens of the State in which the action was originally filed."],[0,"(5) Paragraphs (2) through (4) shall not apply to any class action in which—"],[1,"(A) the primary defendants are States, State officials, or other governmental entities against whom the district court may be foreclosed from ordering relief; or"],[1,"(B) the number of members of all proposed plaintiff classes in the aggregate is less than 100."],[0,"(6) In any class action, the claims of the individual class members shall be aggregated to determine whether the matter in controversy exceeds the sum or value of $5,000,000, exclusive of interest and costs."],[0,"(7) Citizenship of the members of the proposed plaintiff classes shall be determined for purposes of paragraphs (2) through (6) as of the date of filing of the complaint or amended complaint, or, if the case stated by the initial pleading is not subject to Federal jurisdiction, as of the date of service by plaintiffs of an amended pleading, motion, or other paper, indicating the existence of Federal jurisdiction."],[0,"(8) This subsection shall apply to any class action before or after the entry of a class certification order by the court with respect to that action."],[0,"(9) Paragraph (2) shall not apply to any class action that solely involves a claim—"],[1,"(A) concerning a covered security as defined under 16(f)(3) 1 of the Securities Act of 1933 (15 U.S.C. 78p(f)(3) 2) and section 28(f)(5)(E) of the Securities Exchange Act of 1934 (15 U.S.C. 78bb(f)(5)(E));"],[1,"(B) that relates to the internal affairs or governance of a corporation or other form of business enterprise and that arises under or by virtue of the laws of the State in which such corporation or business enterprise is incorporated or organized; or"],[1,"(C) that relates to the rights, duties (including fiduciary duties), and obligations relating to or created by or pursuant to any security (as defined under section 2(a)(1) of the Securities Act of 1933 (15 U.S.C. 77b(a)(1)) and the regulations issued thereunder)."],[0,"(10) For purposes of this subsection and section 1453, an unincorporated association shall be deemed to be a citizen of the State where it has its principal place of business and the State under whose laws it is organized."],[0,"(11)(A) For purposes of this subsection and section 1453, a mass action shall be deemed to be a class action removable under paragraphs (2) through (10) if it otherwise meets the provisions of those paragraphs."],[0,"(B)(i) As used in subparagraph (A), the term \"mass action\" means any civil action (except a civil action within the scope of section 1711(2)) in which monetary relief claims of 100 or more persons are proposed to be tried jointly on the ground that the plaintiffs' claims involve common questions of law or fact, except that jurisdiction shall exist only over those plaintiffs whose claims in a mass action satisfy the jurisdictional amount requirements under subsection (a)."],[0,"(ii) As used in subparagraph (A), the term \"mass action\" shall not include any civil action in which—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1332?type=usc&year=mostrecent&link-type=html"},"head":"§1332. Diversity of citizenship; amount in controversy; costs","tname":"Judiciary and Judicial Procedure","by":{"0":"22","1":"18"}},{"t":"usc","label":"28 U.S.C. § 1340","url":"https://www.law.cornell.edu/uscode/text/28/1340","by":{"0":"24"}},{"t":"usc","label":"28 U.S.C. § 1362","url":"https://www.law.cornell.edu/uscode/text/28/1362","by":{"0":"21"}},{"t":"usc","label":"28 U.S.C. § 1491","url":"https://www.law.cornell.edu/uscode/text/28/1491","subs":["(a)(2)","(a)(1)"],"stext":{"head":"§1491. Claims against United States generally; actions involving Tennessee Valley Authority","paras":[[0,"(a)(1) The United States Court of Federal Claims shall have jurisdiction to render judgment upon any claim against the United States founded either upon the Constitution, or any Act of Congress or any regulation of an executive department, or upon any express or implied contract with the United States, or for liquidated or unliquidated damages in cases not sounding in tort. For the purpose of this paragraph, an express or implied contract with the Army and Air Force Exchange Service, Navy Exchanges, Marine Corps Exchanges, Coast Guard Exchanges, or Exchange Councils of the National Aeronautics and Space Administration shall be considered an express or implied contract with the United States."],[0,"(2) To provide an entire remedy and to complete the relief afforded by the judgment, the court may, as an incident of and collateral to any such judgment, issue orders directing restoration to office or position, placement in appropriate duty or retirement status, and correction of applicable records, and such orders may be issued to any appropriate official of the United States. In any case within its jurisdiction, the court shall have the power to remand appropriate matters to any administrative or executive body or official with such direction as it may deem proper and just. The Court of Federal Claims shall have jurisdiction to render judgment upon any claim by or against, or dispute with, a contractor arising under section 7104(b)(1) of title 41, including a dispute concerning termination of a contract, rights in tangible or intangible property, compliance with cost accounting standards, and other nonmonetary disputes on which a decision of the contracting officer has been issued under section 6 1 of that Act."],[0,"(b)(1) Both the Unites 2 States Court of Federal Claims and the district courts of the United States shall have jurisdiction to render judgment on an action by an interested party objecting to a solicitation by a Federal agency for bids or proposals for a proposed contract or to a proposed award or the award of a contract or any alleged violation of statute or regulation in connection with a procurement or a proposed procurement. Both the United States Court of Federal Claims and the district courts of the United States shall have jurisdiction to entertain such an action without regard to whether suit is instituted before or after the contract is awarded."],[0,"(2) To afford relief in such an action, the courts may award any relief that the court considers proper, including declaratory and injunctive relief except that any monetary relief shall be limited to bid preparation and proposal costs."],[0,"(3) In exercising jurisdiction under this subsection, the courts shall give due regard to the interests of national defense and national security and the need for expeditious resolution of the action."],[0,"(4) In any action under this subsection, the courts shall review the agency's decision pursuant to the standards set forth in section 706 of title 5."],[0,"(5) If an interested party who is a member of the private sector commences an action described in paragraph (1) with respect to a public-private competition conducted under Office of Management and Budget Circular A–76 regarding the performance of an activity or function of a Federal agency, or a decision to convert a function performed by Federal employees to private sector performance without a competition under Office of Management and Budget Circular A–76, then an interested party described in section 3551(2)(B) of title 31 shall be entitled to intervene in that action."],[0,"(6) Jurisdiction over any action described in paragraph (1) arising out of a maritime contract, or a solicitation for a proposed maritime contract, shall be governed by this section and shall not be subject to the jurisdiction of the district courts of the United States under the Suits in Admiralty Act (chapter 309 of title 46) or the Public Vessels Act (chapter 311 of title 46)."],[0,"(c) Nothing herein shall be construed to give the United States Court of Federal Claims jurisdiction of any civil action within the exclusive jurisdiction of the Court of International Trade, or of any action against, or founded on conduct of, the Tennessee Valley Authority, or to amend or modify the provisions of the Tennessee Valley Authority Act of 1933 with respect to actions by or against the Authority."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1491?type=usc&year=mostrecent&link-type=html"},"head":"§1491. Claims against United States generally; actions involving Tennessee Valley Authority","tname":"Judiciary and Judicial Procedure","by":{"0":"21","1":"2"}},{"t":"usc","label":"28 U.S.C. § 2253","url":"https://www.law.cornell.edu/uscode/text/28/2253","subs":["(c)(1)"],"by":{"0":"22"}},{"t":"usc","label":"42 U.S.C. § 1395oo","url":"https://www.law.cornell.edu/uscode/text/42/1395oo","subs":["(a)"],"stext":{"head":"§1395oo. Provider Reimbursement Review Board","paras":[[0,"(a) Establishment"],[0,"Any provider of services which has filed a required cost report within the time specified in regulations may obtain a hearing with respect to such cost report by a Provider Reimbursement Review Board (hereinafter referred to as the \"Board\") which shall be established by the Secretary in accordance with subsection (h) and (except as provided in subsection (g)(2)) any hospital which receives payments in amounts computed under subsection (b) or (d) of section 1395ww of this title and which has submitted such reports within such time as the Secretary may require in order to make payment under such section may obtain a hearing with respect to such payment by the Board, if—"],[1,"(1) such provider—"],[2,"(A)(i) is dissatisfied with a final determination of the organization serving as its fiscal intermediary pursuant to section 1395h of this title as to the amount of total program reimbursement due the provider for the items and services furnished to individuals for which payment may be made under this subchapter for the period covered by such report, or"],[2,"(ii) is dissatisfied with a final determination of the Secretary as to the amount of the payment under subsection (b) or (d) of section 1395ww of this title,"],[2,"(B) has not received such final determination from such intermediary on a timely basis after filing such report, where such report complied with the rules and regulations of the Secretary relating to such report, or"],[2,"(C) has not received such final determination on a timely basis after filing a supplementary cost report, where such cost report did not so comply and such supplementary cost report did so comply,"],[1,"(2) the amount in controversy is $10,000 or more, and"],[1,"(3) such provider files a request for a hearing within 180 days after notice of the intermediary's final determination under paragraph (1)(A)(i), or with respect to appeals under paragraph (1)(A)(ii), 180 days after notice of the Secretary's final determination, or with respect to appeals pursuant to paragraph (1) (B) or (C), within 180 days after notice of such determination would have been received if such determination had been made on a timely basis."],[0,"(b) Appeals by groups"],[0,"The provisions of subsection (a) shall apply to any group of providers of services if each provider of services in such group would, upon the filing of an appeal (but without regard to the $10,000 limitation), be entitled to such a hearing, but only if the matters in controversy involve a common question of fact or interpretation of law or regulations and the amount in controversy is, in the aggregate, $50,000 or more."],[0,"(c) Right to counsel; rules of evidence"],[0,"At such hearing, the provider of services shall have the right to be represented by counsel, to introduce evidence, and to examine and cross-examine witnesses. Evidence may be received at any such hearing even though inadmissible under rules of evidence applicable to court procedure."],[0,"(d) Decisions of Board"],[0,"A decision by the Board shall be based upon the record made at such hearing, which shall include the evidence considered by the intermediary and such other evidence as may be obtained or received by the Board, and shall be supported by substantial evidence when the record is viewed as a whole. The Board shall have the power to affirm, modify, or reverse a final determination of the fiscal intermediary with respect to a cost report and to make any other revisions on matters covered by such cost report (including revisions adverse to the provider of services) even though such matters were not considered by the intermediary in making such final determination."],[0,"(e) Rules and regulations"],[0,"The Board shall have full power and authority to make rules and establish procedures, not inconsistent with the provisions of this subchapter or regulations of the Secretary, which are necessary or appropriate to carry out the provisions of this section. In the course of any hearing the Board may administer oaths and affirmations. The provisions of subsections (d) and (e) of section 405 of this title with respect to subpenas shall apply to the Board to the same extent as they apply to the Secretary with respect to subchapter II."],[0,"(f) Finality of decision; judicial review; determinations of Board authority; jurisdiction; venue; interest on amount in controversy"],[0,"(1) A decision of the Board shall be final unless the Secretary, on his own motion, and within 60 days after the provider of services is notified of the Board's decision, reverses, affirms, or modifies the Board's decision. Providers shall have the right to obtain judicial review of any final decision of the Board, or of any reversal, affirmance, or modification by the Secretary, by a civil action commenced within 60 days of the date on which notice of any final decision by the Board or of any reversal, affirmance, or modification by the Secretary is received. Providers shall also have the right to obtain judicial review of any action of the fiscal intermediary which involves a question of law or regulations relevant to the matters in controversy whenever the Board determines (on its own motion or at the request of a provider of services as described in the following sentence) that it is without authority to decide the question, by a civil action commenced within sixty days of the date on which notification of such determination is received. If a provider of services may obtain a hearing under subsection (a) and has filed a request for such a hearing, such provider may file a request for a determination by the Board of its authority to decide the question of law or regulations relevant to the matters in controversy (accompanied by such documents and materials as the Board shall require for purposes of rendering such determination). The Board shall render such determination in writing within thirty days after the Board receives the request and such accompanying documents and materials, and the determination shall be considered a final decision and not subject to review by the Secretary. If the Board fails to render such determination within such period, the provider may bring a civil action (within sixty days of the end of such period) with respect to the matter in controversy contained in such request for a hearing. Such action shall be brought in the district court of the United States for the judicial district in which the provider is located (or, in an action brought jointly by several providers, the judicial district in which the greatest number of such providers are located) or in the District Court for the District of Columbia and shall be tried pursuant to the applicable provisions under chapter 7 of title 5 notwithstanding any other provisions in section 405 of this title. Any appeal to the Board or action for judicial review by providers which are under common ownership or control or which have obtained a hearing under subsection (b) must be brought by such providers as a group with respect to any matter involving an issue common to such providers."],[0,"(2) Where a provider seeks judicial review pursuant to paragraph (1), the amount in controversy shall be subject to annual interest beginning on the first day of the first month beginning after the 180-day period as determined pursuant to subsection (a)(3) and equal to the rate of interest on obligations issued for purchase by the Federal Hospital Insurance Trust Fund for the month in which the civil action authorized under paragraph (1) is commenced, to be awarded by the reviewing court in favor of the prevailing party."],[0,"(3) No interest awarded pursuant to paragraph (2) shall be deemed income or cost for the purposes of determining reimbursement due providers under this chapter."],[0,"(g) Certain findings not reviewable"],[0,"(1) The finding of a fiscal intermediary that no payment may be made under this subchapter for any expenses incurred for items or services furnished to an individual because such items or services are listed in section 1395y of this title shall not be reviewed by the Board, or by any court pursuant to an action brought under subsection (f)."],[0,"(2) The determinations and other decisions described in section 1395ww(d)(7) of this title shall not be reviewed by the Board or by any court pursuant to an action brought under subsection (f) or otherwise."],[0,"(h) Composition and compensation"],[0,"The Board shall be composed of five members appointed by the Secretary without regard to the provisions of title 5 governing appointments in the competitive services. Two of such members shall be representative of providers of services. All of the members of the Board shall be persons knowledgeable in the field of payment of providers of services, and at least one of them shall be a certified public accountant. Members of the Board shall be entitled to receive compensation at rates fixed by the Secretary, but not exceeding the rate specified (at the time the service involved is rendered by such members) for grade GS–18 in section 5332 of title 5. The term of office shall be three years, except that the Secretary shall appoint the initial members of the Board for shorter terms to the extent necessary to permit staggered terms of office."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1395oo?type=usc&year=mostrecent&link-type=html"},"head":"§1395oo. Provider Reimbursement Review Board","tname":"The Public Health and Welfare","by":{"0":"18","2":"4"}},{"t":"usc","label":"42 U.S.C. § 2000e-16","url":"https://www.law.cornell.edu/uscode/text/42/2000e-16","subs":["(c)"],"by":{"0":"37, 42"}},{"t":"law","label":"Pub. L. No. 104-168","url":"https://www.govinfo.gov/link/plaw/104/public/168","by":{"0":"22"}},{"t":"law","label":"Page(s), Pub. L. No. 105-206","url":"https://www.govinfo.gov/link/plaw/105/public/206","by":{"0":"4, 7, 22"}},{"t":"law","label":"Pub. L. No. 106-554","url":"https://www.govinfo.gov/link/plaw/106/public/554","by":{"0":"24","2":"9"}},{"t":"law","label":"Pub. L. No. 109-280","url":"https://www.govinfo.gov/link/plaw/109/public/280","by":{"0":"7, 25","2":"21"}},{"t":"law","label":"Pub. L. No. 114-113","url":"https://www.govinfo.gov/link/plaw/114/public/113","by":{"0":"42","1":"45","2":"21"}},{"t":"law","label":"Pub. L. No. 116-25","url":"https://www.govinfo.gov/link/plaw/116/public/25","by":{"0":"5","1":"5"}},{"t":"reg","label":"26 C.F.R. § 301.7122-1","url":"https://www.ecfr.gov/current/title-26/section-301.7122-1","subs":["(b)"],"by":{"0":"39"}},{"t":"reg","label":"26 C.F.R. § 301.7508-1","url":"https://www.ecfr.gov/current/title-26/section-301.7508-1","by":{"0":"46"}},{"t":"reg","label":"26 C.F.R. § 301.7508","url":"https://www.ecfr.gov/current/title-26/section-301.7508","by":{"0":"46"}},{"t":"rule","label":"Fed. R. App. P. 2","url":"https://www.law.cornell.edu/rules/frap/rule_2","by":{"0":"44"}},{"t":"rule","label":"Fed. R. App. P. 26","url":"https://www.law.cornell.edu/rules/frap/rule_26","subs":["(b)(1)"],"by":{"0":"44"}},{"t":"case","label":"Andrews v. Commissioner","cite":"563 F.2d 365","y":1977,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/563/365/","by":{"1":"28"}},{"t":"case","label":"Boyd v. Commissioner","cite":"451 F.3d 8","y":2006,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/451/8/","by":{"1":"17"}},{"t":"case","label":"Brown v. Gardner","cite":"513 U.S. 115","y":1994,"id":"1994/93-1128","sc":1,"sum":"The Court affirmed the lower court's decision and ruled for Gardner. The Court held that Section 1151 contains no language requiring proof of fault, and it rejected the Government's claims that the requirement was implicit in the language of the statute.","sumSrc":"Oyez","by":{"1":"30"}},{"t":"case","label":"Bull v. United States","cite":"295 U.S. 247","y":1935,"id":"scdb/1934-123","sc":1,"sum":"'(1) That the taxpayer was entitled to recoup from the amount of the income tax the amount of the unlawful estate tax by suit for the difference in the Court of Claims, although suit to recover the unlawful tax independently had become barred. Pp. 261-262. (2) A complaint by which the taxpayer prayed judgment in the alternative, either for the amount of the income tax or for what should have been credited against it …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"4, 44"}},{"t":"case","label":"California Pub. Emps.’ Ret. Sys. v. ANZ Sec., Inc.","cite":"137 S. Ct. 2042","y":2017,"id":"2016/16-373","sc":1,"sum":"The Court determined that the filing of a putative class action lawsuit does not satisfy the three-year time limit in Section 13 of the Securities Act with respect to the individual claims of other class members.","sumSrc":"Oyez","by":{"1":"25, 26, 41","2":"10, 11"}},{"t":"case","label":"CIC Servs., LLC v. IRS","cite":"141 S. Ct. 1582","y":2021,"id":"2020/19-930","sc":1,"sum":"A suit to enjoin IRS Notice 2016–66 does not trigger the Anti-Injunction Act even though a violation of the Notice may result in a tax penalty.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"2"}},{"t":"case","label":"Commissioner v. McCoy","cite":"484 U.S. 3","y":1987,"id":"1987/87-75","sc":1,"sum":"The Court of Appeals exceeded its jurisdictional authority when it granted the petition to forgive interest and the late-payment penalty. Section 7482(a) of the Code gives the courts of appeals jurisdiction to review Tax Court decisions \"in the same manner and to the same extent as decisions of the district courts in civil actions tried without a jury,\" while §7482(c)(1) provides that \"such courts shall have the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"26, 43","2":"18"}},{"t":"case","label":"District of Columbia v. Heller","cite":"554 U.S. 570","y":2008,"id":"2007/07-290","sc":1,"sum":"The Court found a District of Columbia law strictly regulating gun ownership to be unconstitutional.","sumSrc":"Oyez","by":{"1":"32"}},{"t":"case","label":"Encino Motorcars, LLC v. Navarro","cite":"138 S. Ct. 1134","y":2018,"id":"2017/16-1362","sc":1,"sum":"The Court decided that because service advisors at car dealerships are “salesm[e]n . . . primarily engaged in . . . servicing automobiles,” 29 U.S.C. § 213(b)(10)(A), they are exempt from the Fair Labor Standards Act's overtime-pay requirements.","sumSrc":"Oyez","by":{"1":"37"}},{"t":"case","label":"Flora v. United States","cite":"357 U.S. 63","y":1958,"id":"scdb/1957-118","sc":1,"sum":"A taxpayer must pay the full amount of an income tax deficiency assessed by the Commissioner of Internal Revenue before he may challenge its correctness by a suit in a federal district court for refund under 28 U. S. C. § 1346 (a) (1). Pp. 63-76. 246 F. 2d 929, affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"2"}},{"t":"case","label":"G.M. Leasing Corp. v. United States","cite":"429 U.S. 338","y":1977,"id":"1976/75-235","sc":1,"sum":"The Internal Revenue Service (IRS), having investigated the income tax liability of a taxpayer who was a fugitive from justice, determined deficiencies for two taxable years, and because of the taxpayer's failure to file proper returns and his fugitive status, made jeopardy assessments pursuant to § 6861 (a) of the Internal Revenue Code of 1954. Petitioner corporation was determined to be the alter ego of the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"2, 4"}},{"t":"case","label":"Gray v. Commissioner","cite":"723 F.3d 790","y":2013,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/723/790/","by":{"1":"17"}},{"t":"case","label":"Guerrero-Lasprilla v. Barr","cite":"140 S. Ct. 1062","y":2020,"id":"2019/18-776","sc":1,"sum":"The Court held that the phrase “questions of law” in the Immigration and Nationality Act’s Limited Review Provision, 8 U. S. C. §1252(a)(2)(D), includes the application of a legal standard to undisputed or established facts.","sumSrc":"Oyez","by":{"1":"27"}},{"t":"case","label":"Hauptman v. Commissioner","cite":"831 F.3d 950","y":2016,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/831/950/","by":{"1":"11"}},{"t":"case","label":"Intel Corp. Inv. Policy Comm. v. Sulyma","cite":"140 S. Ct. 768","y":2020,"id":"2019/18-1116","sc":1,"sum":"The Court held that under the Employee Retirement Income Security Act of 1974 requirement that plaintiffs with “actual knowledge” of an alleged fiduciary breach must file suit within three years of gaining that knowledge, a plaintiff does not necessarily have “actual knowledge” of the information contained in disclosures that he receives but does not read or cannot recall reading.","sumSrc":"Oyez","by":{"1":"36"}},{"t":"case","label":"Johnson v. Commissioner","cite":"611 F.2d 1015","y":1980,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/611/1015/","by":{"1":"28"}},{"t":"case","label":"Kaplan v. Commissioner","cite":"552 Fed. Appx. 77","y":2014,"court":"2d Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./552/77/","by":{"1":"17"}},{"t":"case","label":"Lozano v. Montoya Alvarez","cite":"572 U.S. 1","y":2014,"id":"2013/12-820","sc":1,"op":1,"sum":"The Court held that the policy of equitable tolling does not apply to the statute of limitations outlined in the Hauge Convention's provision on international child abduction.","sumSrc":"Oyez","by":{"1":"41, 46"}},{"t":"case","label":"Matuszak v. Commissioner","cite":"862 F.3d 192","y":2017,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/862/192/","by":{"1":"24"}},{"t":"case","label":"McNeil v. United States","cite":"2002 WL 507821","y":2002,"court":"W.D. Mich. Mar. 7","by":{"1":"36"}},{"t":"case","label":"Menominee Indian Tribe of Wisc. v. United States","cite":"577 U.S. 250","y":2016,"id":"2015/14-510","sc":1,"sum":"The Court determined that there were no extraordinary circumstances out of the Menominee Indian Tribe’s control to toll the statute of limitations from running.","sumSrc":"Oyez","by":{"1":"47"}},{"t":"case","label":"Merck & Co. v. Reynolds","cite":"559 U.S. 633","y":2010,"id":"2009/08-905","sc":1,"sum":"The Court held that a statute of limitations begins to run once a plaintiff actually discovers -- or a reasonably diligent plaintiff would have discovered -- the facts constituting the violation in the present case, whichever comes first.","sumSrc":"Oyez","by":{"1":"27"}},{"t":"case","label":"Milner v. Department of the Navy","cite":"562 U.S. 562","y":2011,"id":"2010/09-1163","sc":1,"op":2,"sum":"The Court held that documents related to the effect of explosions from Navy exercises did not qualify for withholding under Exception 2 of the Freedom of Information Act.","sumSrc":"Oyez","by":{"1":"37"}},{"t":"case","label":"Nauflett v. Commissioner","cite":"892 F.3d 649","y":2018,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/892/649/","sum":"Concluding that 26 U.S.C. 6015(e)(1)’s filing deadline for a petition for review of an innocent-spouse determination is jurisdictional based in part on a similar provision.","sumSrc":"brief:1","by":{"1":"24"}},{"t":"case","label":"Negusie v. Holder","cite":"555 U.S. 511","y":2009,"id":"2008/07-499","sc":1,"sum":"The Court held that the Board of Immigration Appeals (BIA) incorrectly interpreted provisions of the Immigration and Nationality Act (INA) from a mistaken legal premise.","sumSrc":"Oyez","by":{"1":"22"}},{"t":"case","label":"Organic Cannabis Found., LLC v. Commissioner","cite":"962 F.3d 1082","y":2020,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/962/1082/","ar":1,"sum":"Concluding that 26 U.S.C. 6213(a)’s filing deadline for a petition for redetermination of a tax deficiency is jurisdictional, in part because it “seems clearly to reflect an understanding that the manner in which the Tax Court acquires jurisdiction over a deficiency dispute is through the filing of a ‘timely petition’ ” (citation omitted).","sumSrc":"brief:1","by":{"1":"24, 25, 28"}},{"t":"case","label":"Phillips v. Commissioner","cite":"283 U.S. 589","y":1931,"id":"scdb/1930-077","sc":1,"sum":"1. Stockholders who have received the assets of a dissolved corporation may be compelled to discharge therefrom the unpaid federal taxes on the income and excess profits of the corporation.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"4"}},{"t":"case","label":"Pollock v. Commissioner","cite":"132 T.C. 21","y":2009,"url":"https://www.courtlistener.com/c/T.C./132/21/","ar":1,"by":{"1":"11","2":"18"}},{"t":"case","label":"Pugsley v. Commissioner","cite":"749 F.2d 691","y":1985,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/749/691/","by":{"1":"28"}},{"t":"case","label":"Rotkiske v. Klemm","cite":"140 S. Ct. 355","y":2019,"id":"2019/18-328","sc":1,"sum":"The Court held that the one-year statute of limitations under the Fair Debt Collection Practices Act begins when the violation occurred, not when the violation was discovered.","sumSrc":"Oyez","by":{"1":"26"}},{"t":"case","label":"Rubel v. Commissioner","cite":"856 F.3d 301","y":2017,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/856/301/","by":{"1":"24, 27"}},{"t":"case","label":"Ryan v. Alexander","cite":"118 F.2d 744","y":1941,"url":"https://www.courtlistener.com/c/F.2d/118/744/","by":{"1":"28"}},{"t":"case","label":"Salinas v. United States R.R. Ret. Bd.","cite":"141 S. Ct. 691","y":2021,"id":"2020/19-199","sc":1,"sum":"The U. S. Railroad Retirement Board’s denial of a request to reopen a prior benefits determination under the Railroad Retirement Act of 1974 and the Railroad Unemployment Insurance Act is subject to judicial review.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"19","2":"2"}},{"t":"case","label":"Sarrell v. Commissioner","cite":"117 T.C. 122","y":2001,"url":"https://www.courtlistener.com/c/T.C./117/122/","by":{"1":"36","2":"15"}},{"t":"case","label":"Shipley v. Commissioner","cite":"572 F.2d 212","y":1977,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/572/212/","by":{"1":"28"}},{"t":"case","label":"Springer v. Commissioner","cite":"416 Fed. Appx. 681","y":2011,"court":"10th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./416/681/","by":{"1":"17"}},{"t":"case","label":"Tadros v. Commissioner","cite":"763 F.2d 89","y":1985,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/763/89/","by":{"1":"28","2":"14"}},{"t":"case","label":"Tilden v. Commissioner","cite":"846 F.3d 882","y":2017,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/846/882/","by":{"1":"24"}},{"t":"case","label":"Torres v. Lynch","cite":"578 U.S. 452","y":2016,"id":"2015/14-1096","sc":1,"sum":"The Court determined that a state offense may constitute an aggravated felony for the purpose of the removal of a permanent resident when it includes all the elements of the federal statute with the exception of the interstate commerce element.","sumSrc":"Oyez","by":{"1":"22"}},{"t":"case","label":"Tuka v. Commissioner","cite":"348 Fed. Appx. 819","y":2009,"court":"3d Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./348/819/","by":{"1":"17"}},{"t":"case","label":"Ulloa v. United States","cite":"2005 WL 2739105","y":2005,"court":"N.D.N.Y. Oct. 24","by":{"1":"36"}},{"t":"case","label":"United Sav. Ass’n v. Timbers of Inwood Forest Assocs., Ltd.","cite":"484 U.S. 365","y":1988,"id":"1987/86-1602","sc":1,"sum":"Undersecured creditors are not entitled to compensation under § 362(d)(1) for the delay caused by the automatic stay in foreclosing on their collateral.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"23, 30"}},{"t":"case","label":"United States v. Clintwood Elkhorn Mining Co.","cite":"553 U.S. 1","y":2008,"id":"2007/07-308","sc":1,"sum":"Jr., the Court refused to pay Clintwood refunds for the unconstitutionally levied taxes. The Court stated that the remedy for taxes imposed in violation of the Export Clause is the same as for any other unlawful tax: filing a timely administrative refund claim.","sumSrc":"Oyez","by":{"1":"2"}},{"t":"case","label":"United States v. National Bank of Commerce","cite":"472 U.S. 713","y":1985,"id":"1984/84-498","sc":1,"sum":"The IRS had a right to levy on the joint accounts in question.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"44"}},{"t":"case","label":"Walz v. United States","cite":"2002 WL 523880","y":2002,"court":"D. Minn. Mar. 22","by":{"1":"36"}},{"t":"usc","label":"28 U.S.C. § 2201","url":"https://www.law.cornell.edu/uscode/text/28/2201","subs":["(a)"],"by":{"1":"3"}},{"t":"usc","label":"28 U.S.C. § 1330","url":"https://www.law.cornell.edu/uscode/text/28/1330","by":{"1":"19"}},{"t":"usc","label":"28 U.S.C. § 1346","url":"https://www.law.cornell.edu/uscode/text/28/1346","subs":["(a)(1)"],"by":{"1":"2"}},{"t":"rule","label":"Fed. R. Civ. P. 23","url":"https://www.law.cornell.edu/rules/frcp/rule_23","by":{"1":"41"}},{"t":"case","label":"Almendarez-Torres v. United States","cite":"523 U.S. 224","y":1998,"id":"1997/96-6839","sc":1,"sum":"The Court held that subsection (b)(2) of 8 USC section 1326(a) is a penalty provision, which authorizes a court to increase the sentence for a recidivist, and does not define a separate crime. \"[W]e note that the relevant statutory subject matter is recidivism,\" wrote Justice Breyer, \"[t]hat subject matter -- prior commission of a serious crime -- is as typical a sentencing factor as one might imagine.\" Therefore, neither subsection (b)(2) nor the due process clause of the Fifth Amendment required that the government charge a prior aggravated felony conviction in the alien's indictment for the imposition of a sentence more than 2 years.","sumSrc":"Oyez","by":{"2":"8"}},{"t":"case","label":"American Pipe & Construction Co. v. Utah","cite":"414 U.S. 538","y":1974,"id":"1973/72-1195","sc":1,"sum":"The Court held that commencing a class action suspends all applicable statutes of limitations against members of that class who would have been parties had the suit been allowed to continue as a class action.","sumSrc":"Oyez","by":{"2":"11"}},{"t":"case","label":"Artis v. District of Columbia","cite":"138 S. Ct. 594","y":2018,"id":"2017/16-460","sc":1,"ar":1,"sum":"The Court decided that the tolling provision of 28 U.S.C. § 1367 suspends or “stops the clock” on the limitations period for supplemental state law claims while the underlying case is pending in federal court and for 30 days thereafter, rather than merely providing a 30-day grace period after dismissal for the plaintiff to refile in state court.","sumSrc":"Oyez","by":{"2":"10, 11"}},{"t":"case","label":"BNSF Railway Co. v. Loos","cite":"139 S. Ct. 893","y":2019,"id":"2018/17-1042","sc":1,"sum":"A railroad’s payment to an employee for working time lost due to an on-the-job injury is taxable “compensation” under the Railroad Retirement Tax Act.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"8"}},{"t":"case","label":"Bokum v. Commissioner","cite":"992 F.2d 1136","y":1993,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/992/1136/","by":{"2":"18"}},{"t":"case","label":"Boyd v. Ward","cite":"56 F. App’x 849","y":2002,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/56/849/","by":{"2":"10"}},{"t":"case","label":"Brown v. United States","cite":"318 F. App’x 749","y":2008,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/318/749/","by":{"2":"10"}},{"t":"case","label":"Dixon v. McDonald","cite":"815 F.3d 799","y":2016,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/815/799/","by":{"2":"19"}},{"t":"case","label":"Dogwood Forest Rest Home, Inc. v. United States","cite":"181 F. Supp. 2d 554","y":2001,"court":"M.D.N.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/181/554/","by":{"2":"8"}},{"t":"case","label":"Estate of Branson v. Commissioner","cite":"264 F.3d 904","y":2001,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/264/904/","by":{"2":"18"}},{"t":"case","label":"FAA v. Cooper","cite":"566 U.S. 284","y":2012,"id":"2011/10-1024","sc":1,"sum":"The Court held that the Privacy Act of 1974 does not cover mental and emotional distress under \"actual damages.\"","sumSrc":"Oyez","by":{"2":"2, 3"}},{"t":"case","label":"Flight Attendants Against UAL Offset v. Commissioner","cite":"165 F.3d 572","y":1999,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/165/572/","by":{"2":"19"}},{"t":"case","label":"Freytag v. Commissioner","cite":"501 U.S. 868","y":1991,"id":"1990/90-762","sc":1,"ar":1,"sum":"On the question of whether 7443A permitted the assignment of complex cases to special trial judges, the Supreme Court unanimously ruled that the statute unambiguously did allow such appointments. Justice Harry Blackmun, in the majority opinion, wrote, \"The plain language of 7443A(b)(4) surely authorizes the Chief Judge's assignment of petitioners' cases to a special trial judge.","sumSrc":"Oyez","by":{"2":"18"}},{"t":"case","label":"Goosby v. Commissioner, T.C. Memo. 2019-49","cite":"2019 WL 2060795","by":{"2":"11"}},{"t":"case","label":"Harper v. Ercole","cite":"648 F.3d 132","y":2011,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/648/132/","by":{"2":"10"}},{"t":"case","label":"Lewis-Hall Iron Works v. Blair","cite":"23 F.2d 972","y":1928,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/23/972/","by":{"2":"14"}},{"t":"case","label":"Moore v. Commissioner","cite":"114 T.C. 171","y":2000,"url":"https://www.courtlistener.com/c/T.C./114/171/","by":{"2":"8"}},{"t":"case","label":"Scarborough v. Principi","cite":"541 U.S. 401","y":2004,"id":"2003/02-1657","sc":1,"sum":"In a 7-to-2 opinion written by Justice Ruth Bader Ginsburg, the Court held that the statement on the application that the government's position had not been \"substantially justified\" was merely procedural. There was no need to prove the assertion - the applicant merely had to make the claim to shift the burden of proof to the government.","sumSrc":"Oyez","by":{"2":"17"}},{"t":"case","label":"United States v. Ibarra","cite":"502 U.S. 1","y":1991,"id":"1991/90-1713","sc":1,"sum":"The Government's appeal was timely. All motions for reconsideration are subsumed under one general rule-the rule laid down in Healy. If a merits inquiry were grafted onto the general rule, litigants would 1 UNITED STATES v. IBARRA","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"10"}},{"t":"usc","label":"26 U.S.C. § 6213","url":"https://www.law.cornell.edu/uscode/text/26/6213","subs":["(a)"],"stext":{"head":"§6213. Restrictions applicable to deficiencies; petition to Tax Court","paras":[[0,"(a) Time for filing petition and restriction on assessment"],[0,"Within 90 days, or 150 days if the notice is addressed to a person outside the United States, after the notice of deficiency authorized in section 6212 is mailed (not counting Saturday, Sunday, or a legal holiday in the District of Columbia as the last day), the taxpayer may file a petition with the Tax Court for a redetermination of the deficiency. Except as otherwise provided in section 6851, 6852, or 6861 no assessment of a deficiency in respect of any tax imposed by subtitle A, or B, chapter 41, 42, 43, or 44 and no levy or proceeding in court for its collection shall be made, begun, or prosecuted until such notice has been mailed to the taxpayer, nor until the expiration of such 90-day or 150-day period, as the case may be, nor, if a petition has been filed with the Tax Court, until the decision of the Tax Court has become final. Notwithstanding the provisions of section 7421(a), the making of such assessment or the beginning of such proceeding or levy during the time such prohibition is in force may be enjoined by a proceeding in the proper court, including the Tax Court, and a refund may be ordered by such court of any amount collected within the period during which the Secretary is prohibited from collecting by levy or through a proceeding in court under the provisions of this subsection. The Tax Court shall have no jurisdiction to enjoin any action or proceeding or order any refund under this subsection unless a timely petition for a redetermination of the deficiency has been filed and then only in respect of the deficiency that is the subject of such petition. Any petition filed with the Tax Court on or before the last date specified for filing such petition by the Secretary in the notice of deficiency shall be treated as timely filed."],[0,"(b) Exceptions to restrictions on assessment"],[0,"(1) Assessments arising out of mathematical or clerical errors"],[1,"If the taxpayer is notified that, on account of a mathematical or clerical error appearing on the return, an amount of tax in excess of that shown on the return is due, and that an assessment of the tax has been or will be made on the basis of what would have been the correct amount of tax but for the mathematical or clerical error, such notice shall not be considered as a notice of deficiency for the purposes of subsection (a) (prohibiting assessment and collection until notice of the deficiency has been mailed), or of section 6212(c)(1) (restricting further deficiency letters), or of section 6512(a) (prohibiting credits or refunds after petition to the Tax Court), and the taxpayer shall have no right to file a petition with the Tax Court based on such notice, nor shall such assessment or collection be prohibited by the provisions of subsection (a) of this section. Each notice under this paragraph shall set forth the error alleged and an explanation thereof."],[0,"(2) Abatement of assessment of mathematical or clerical errors"],[0,"(A) Request for abatement"],[2,"Notwithstanding section 6404(b), a taxpayer may file with the Secretary within 60 days after notice is sent under paragraph (1) a request for an abatement of any assessment specified in such notice, and upon receipt of such request, the Secretary shall abate the assessment. Any reassessment of the tax with respect to which an abatement is made under this subparagraph shall be subject to the deficiency procedures prescribed by this subchapter."],[0,"(B) Stay of collection"],[2,"In the case of any assessment referred to in paragraph (1), notwithstanding paragraph (1), no levy or proceeding in court for the collection of such assessment shall be made, begun, or prosecuted during the period in which such assessment may be abated under this paragraph."],[0,"(3) Assessments arising out of tentative carryback or refund adjustments"],[1,"If the Secretary determines that the amount applied, credited, or refunded under section 6411 is in excess of the overassessment attributable to the carryback or the amount described in section 1341(b)(1) with respect to which such amount was applied, credited, or refunded, he may assess without regard to the provisions of paragraph (2) the amount of the excess as a deficiency as if it were due to a mathematical or clerical error appearing on the return."],[0,"(4) Assessment of amount paid"],[1,"Any amount paid as a tax or in respect of a tax may be assessed upon the receipt of such payment notwithstanding the provisions of subsection (a). In any case where such amount is paid after the mailing of a notice of deficiency under section 6212, such payment shall not deprive the Tax Court of jurisdiction over such deficiency determined under section 6211 without regard to such assessment."],[0,"(5) Certain orders of criminal restitution"],[1,"If the taxpayer is notified that an assessment has been or will be made pursuant to section 6201(a)(4)—"],[2,"(A) such notice shall not be considered as a notice of deficiency for the purposes of subsection (a) (prohibiting assessment and collection until notice of the deficiency has been mailed), section 6212(c)(1) (restricting further deficiency letters), or section 6512(a) (prohibiting credits or refunds after petition to the Tax Court), and"],[2,"(B) subsection (a) shall not apply with respect to the amount of such assessment."],[0,"(c) Failure to file petition"],[0,"If the taxpayer does not file a petition with the Tax Court within the time prescribed in subsection (a), the deficiency, notice of which has been mailed to the taxpayer, shall be assessed, and shall be paid upon notice and demand from the Secretary."],[0,"(d) Waiver of restrictions"],[0,"The taxpayer shall at any time (whether or not a notice of deficiency has been issued) have the right, by a signed notice in writing filed with the Secretary, to waive the restrictions provided in subsection (a) on the assessment and collection of the whole or any part of the deficiency."],[0,"(e) Suspension of filing period for certain excise taxes"],[0,"The running of the time prescribed by subsection (a) for filing a petition in the Tax Court with respect to the taxes imposed by section 4941 (relating to taxes on self-dealing), 4942 (relating to taxes on failure to distribute income), 4943 (relating to taxes on excess business holdings), 4944 (relating to investments which jeopardize charitable purpose), 4945 (relating to taxes on taxable expenditures), 4951 (relating to taxes on self-dealing), or 4952 (relating to taxes on taxable expenditures), 4955 (relating to taxes on political expenditures), 4958 (relating to private excess benefit), 4971 (relating to excise taxes on failure to meet minimum funding standard), 4975 (relating to excise taxes on prohibited transactions) shall be suspended for any period during which the Secretary has extended the time allowed for making correction under section 4963(e)."],[0,"(f) Coordination with title 11"],[0,"(1) Suspension of running of period for filing petition in title 11 cases"],[1,"In any case under title 11 of the United States Code, the running of the time prescribed by subsection (a) for filing a petition in the Tax Court with respect to any deficiency shall be suspended for the period during which the debtor is prohibited by reason of such case from filing a petition in the Tax Court with respect to such deficiency, and for 60 days thereafter."],[0,"(2) Certain action not taken into account"],[1,"For purposes of the second and third sentences of subsection (a), the filing of a proof of claim or request for payment (or the taking of any other action) in a case under title 11 of the United States Code shall not be treated as action prohibited by such second sentence."],[0,"(g) Definitions"],[0,"For purposes of this section—"],[0,"(1) Return"],[1,"The term \"return\" includes any return, statement, schedule, or list, and any amendment or supplement thereto, filed with respect to any tax imposed by subtitle A or B, or chapter 41, 42, 43, or 44."],[0,"(2) Mathematical or clerical error"],[1,"The term \"mathematical or clerical error\" means—"],[2,"(A) an error in addition, subtraction, multiplication, or division shown on any return,"],[2,"(B) an incorrect use of any table provided by the Internal Revenue Service with respect to any return if such incorrect use is apparent from the existence of other information on the return,"],[2,"(C) an entry on a return of an item which is inconsistent with another entry of the same or another item on such return,"],[2,"(D) an omission of information which is required to be supplied on the return to substantiate an entry on the return,"],[2,"(E) an entry on a return of a deduction or credit in an amount which exceeds a statutory limit imposed by subtitle A or B, or chapter 41, 42, 43, or 44, if such limit is expressed—"],[3,"(i) as a specified monetary amount, or"],[3,"(ii) as a percentage, ratio, or fraction,"],[2,"and if the items entering into the application of such limit appear on such return,"],[2,"(F) an omission of a correct taxpayer identification number required under section 32 (relating to the earned income credit) to be included on a return,"],[2,"(G) an entry on a return claiming the credit under section 32 with respect to net earnings from self-employment described in section 32(c)(2)(A) to the extent the tax imposed by section 1401 (relating to self-employment tax) on such net earnings has not been paid,"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/6213?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§6213. Restrictions applicable to deficiencies; petition to Tax Court","tname":"Internal Revenue Code","by":{"2":"13"}},{"t":"usc","label":"26 U.S.C. § 6532","url":"https://www.law.cornell.edu/uscode/text/26/6532","subs":["(a)(2)"],"by":{"2":"12"}},{"t":"usc","label":"26 U.S.C. § 6673","url":"https://www.law.cornell.edu/uscode/text/26/6673","subs":["(a)(1)(A)"],"by":{"2":"22"}},{"t":"usc","label":"28 U.S.C. § 1251","url":"https://www.law.cornell.edu/uscode/text/28/1251","subs":["(a)"],"by":{"2":"5"}},{"t":"usc","label":"28 U.S.C. § 1295","url":"https://www.law.cornell.edu/uscode/text/28/1295","subs":["(a)(4)(A)"],"by":{"2":"5"}},{"t":"law","label":"Pub. L. No. 117-58","url":"https://www.govinfo.gov/link/plaw/117/public/58","by":{"2":"22"}},{"t":"reg","label":"26 C.F.R. § 301.7609-5","url":"https://www.ecfr.gov/current/title-26/section-301.7609-5","by":{"2":"12"}}]};